import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = None
        self.open_spi()

    def open_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except (OSError, IOError) as e:
            print(f"Failed to open SPI device: {e}")
            sys.exit(1)

    def read_raw_data(self):
        try:
            response = self.send_spi_command(self.spi, [0x01, 0x80, 0x00])
            return self.extract_10bit(response)
        except (OSError, IOError) as e:
            print(f"SPI communication error: {e}")
            return None

    def send_spi_command(self, spi, data):
        return spi.xfer2(data)

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def convert_to_weight(self, raw_data):
        if raw_data is not None:
            return float(raw_data) * (5.0 / 1023.0)
        return None

    def close(self):
        if self.spi:
            try:
                self.spi.close()
            except (OSError, IOError) as e:
                print(f"Failed to close SPI device: {e}")

def signal_handler(sig, frame):
    print("Received termination signal. Shutting down...")
    reader.close()
    sys.exit(0)

def main():
    global reader
    reader = LoadCellReader()
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            raw_data = reader.read_raw_data()
            weight = reader.convert_to_weight(raw_data)
            if weight is not None:
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        reader.close()
        print("SPI device closed. Program terminated.")

if __name__ == "__main__":
    main()

