class MotionSensor:
    def __init__(self, pin, threshold=2, sampling_period=1.0, debug_mode=False):
        self.pin = pin
        self.threshold = threshold
        self.sampling_period = sampling_period
        self.debug_mode = debug_mode
        self.event_count = 0
        self.lock = threading.Lock()
        self.setup_gpio()

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            GPIO.add_event_detect(self.pin, GPIO.RISING, callback=self.event_callback, bouncetime=200)
            logger.info(f"GPIO {self.pin} set up for motion detection.")
        except Exception as e:
            logger.error(f"Error setting up GPIO {self.pin}: {e}")
            raise

    def event_callback(self, channel):
        try:
            with self.lock:
                self.event_count += 1
            logger.debug(f"Motion detected on pin {self.pin}. Event count: {self.event_count}")
        except Exception as e:
            logger.error(f"Error in event callback for pin {self.pin}: {e}")

    def check_threshold(self):
        with self.lock:
            count = self.event_count
            self.event_count = 0
        return count > self.threshold

    def reset_counter(self):
        with self.lock:
            self.event_count = 0

class LightingController:
    def __init__(self, led_pin, motion_sensor, debug_mode=False):
        self.led_pin = led_pin
        self.motion_sensor = motion_sensor
        self.debug_mode = debug_mode
        self.led_state = False
        self.off_delay = 300
        self.last_motion_time = None
        self.timer = None
        self.setup_gpio()

    def setup_gpio(self):
        try:
            GPIO.setup(self.led_pin, GPIO.OUT)
            GPIO.output(self.led_pin, GPIO.LOW)
            logger.info(f"GPIO {self.led_pin} set up for LED control.")
