import spidev
import numpy as np
import csv
import logging
import signal
import sys
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoilMoistureSensor:
    def __init__(self, dry=820, wet=400):
        self.spi = None
        self.dry = dry
        self.wet = wet
        self.history = []
        self.max_history = 25
        self.setup_spi()

    def setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 1200000
        except Exception as e:
            logging.error(f"Failed to open SPI device: {e}")
            sys.exit(1)

    def read_adc(self, channel):
        if channel < 0 or channel > 7:
            raise ValueError("Channel must be an integer between 0 and 7")

        # Construct the command
        command = [1, (8 + channel) << 4, 0]
        try:
            response = self.spi.xfer2(command)
            adc_value = ((response[1] & 3) << 8) + response[2]
            return adc_value
        except Exception as e:
            logging.error(f"SPI communication error: {e}")
            return None

    def read_moisture(self):
        raw_value = self.read_adc(2)
        if raw_value is None:
            return None

        if raw_value == 0 or raw_value == 1023:
            logging.warning("Sensor absent or disconnected, returning None")
            return None

        # Calibrate the raw value to a percentage
        moisture_percentage = 100 * (self.dry - raw_value) / (self.dry - self.wet)
        return max(0, min(100, moisture_percentage))

    def update_history(self, value):
        self.history.append(value)
        if len(self.history) > self.max_history:
            self.history.pop(0)

    def compute_statistics(self):
        if not self.history:
            return None, None
        mean = np.mean(self.history)
        std_dev = np.std(self.history)
        return mean, std_dev

    def log_reading(self, timestamp, moisture_percentage):
        with open('soil_moisture_log.csv', mode='a', newline='') as file:
            writer = csv.writer(file)
            writer.writerow([timestamp, moisture_percentage])

    def cleanup(self):
        if self.spi:
            self.spi.close()

def signal_handler(sig, frame):
    logging.info("Signal received, cleaning up and exiting.")
    sensor.cleanup()
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    sensor = SoilMoistureSensor()

    try:
        with open('soil_moisture_log.csv', mode='w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(['timestamp', 'moisture_percentage'])

        for _ in range(25):
            moisture_percentage = sensor.read_moisture()
            if moisture_percentage is not None:
                timestamp = datetime.now().isoformat()
                sensor.log_reading(timestamp, moisture_percentage)
                sensor.update_history(moisture_percentage)
                mean, std_dev = sensor.compute_statistics()
                logging.info(f"Moisture: {moisture_percentage:.2f}%, Mean: {mean:.2f}%, Std Dev: {std_dev:.2f}%")
            else:
                logging.warning("Failed to read moisture value.")
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Interrupted by user, cleaning up.")
    finally:
        sensor.cleanup()

if __name__ == "__main__":
    main()

import spidev
import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    def __init__(self, spi_bus=0, spi_device=0, pump_pin=18, dry_threshold=450):
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.pump_pin = pump_pin
        self.dry_threshold = dry_threshold
        self.spi = None
        self.pump_gpio = None

        try:
            # Setup SPI
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = 1350000
            self.spi.mode = 0b00

            # Setup GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
            self.pump_gpio = GPIO.PWM(self.pump_pin, 1000)  # Set frequency to 1kHz
            self.pump_gpio.start(0)  # Start with 0% duty cycle

        except Exception as e:
            logging.error(f"Initialization error: {e}")
            self.close()

    def read_moisture(self):
        try:
            # MCP3008 command format: start bit, single-ended mode, channel select
            command = [1, 8 + 0, 0]  # Start bit, single-ended, channel 0
            response = self.spi.xfer2(command)
            adc_value = ((response[1] & 3) << 8) + response[2]
            logging.info(f"Raw moisture value: {adc_value}")
            return adc_value
        except Exception as e:
            logging.error(f"SPI transaction error: {e}")
            return None

    def run_pump(self, seconds):
        try:
            self.pump_gpio.ChangeDutyCycle(100)  # 100% duty cycle
            time.sleep(seconds)
            self.pump_gpio.ChangeDutyCycle(0)  # Stop pump
        except Exception as e:
            logging.error(f"Error running pump: {e}")

    def irrigation_cycle(self):
        moisture_value = self.read_moisture()
        if moisture_value is None:
            return False

        if moisture_value > self.dry_threshold:
            self.run_pump(2)
            return True
        return False

    def close(self):
        try:
            if self.spi:
                self.spi.close()
            if self.pump_gpio:
                self.pump_gpio.stop()
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"Cleanup error: {e}")

def schedule_cycles(controller, cycle_count, interval_seconds):
    try:
        for _ in range(cycle_count):
            watered = controller.irrigation_cycle()
            logging.info(f"Cycle completed. Watered: {watered}")
            time.sleep(interval_seconds)
    except KeyboardInterrupt:
        logging.info("Schedule interrupted by user.")
    finally:
        controller.close()

if __name__ == "__main__":
    controller = SmartGardenController()
    try:
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        controller.close()

