import argparse
import logging
import queue
import signal
import spidev
import threading
import time
import RPi.GPIO as GPIO
from gpiozero import DigitalInputDevice
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn
import adafruit_mcp3xxx as MCP
import board

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.log_queue = log_queue
        self.running = False
        self.last_event_time = 0

        if sensor_type == 'digital':
            if not gpio_pins:
                raise ValueError("GPIO pins must be provided for digital sensors.")
            self.devices = [DigitalInputDevice(pin) for pin in gpio_pins]
        elif sensor_type == 'analog':
            if not channels:
                raise ValueError("Channels must be provided for analog sensors.")
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = spi_speed
                self.adc = MCP.MCP3008(spi=self.spi)
                self.channels = [AnalogIn(self.adc, channel) for channel in channels]
            except Exception as e:
                logging.error(f"SPI initialization failed for sensor {sensor_id}: {e}")
                raise
        else:
            raise ValueError("Invalid sensor type. Must be 'digital' or 'analog'.")

    def read_analog(self, channel):
        try:
            return channel.value * 3.3  # Assuming a 3.3V reference
        except Exception as e:
            logging.error(f"Analog read error on channel {channel.channel}: {e}")
            return None

    def run(self):
        self.running = True
        while self.running:
            try:
                if self.sensor_type == 'digital':
                    for device in self.devices:
                        if device.value == 1 and time.time() - self.last_event_time > 0.1:
                            self.log_event(f"Digital sound detected on pin {device.pin}")
                            self.last_event_time = time.time()
                elif self.sensor_type == 'analog':
                    for channel in self.channels:
                        value = self.read_analog(channel)
                        if value is not None and value >= self.threshold and time.time() - self.last_event_time > 0.1:
                            self.log_event(f"Analog sound detected on channel {channel.channel} with value {value}")
                            self.last_event_time = time.time()
                time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in run loop for sensor {self.sensor_id}: {e}")

    def log_event(self, message):
        if self.log_queue:
            self.log_queue.put(message)

    def stop(self):
        self.running = False
        if self.sensor_type == 'analog':
            self.spi.close()
        elif self.sensor_type == 'digital':
            for device in self.devices:
                device.close()

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitor")
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'], help="Type of sensor")
    parser.add_argument('--threshold', type=float, required=True, help="Threshold for analog sensors")
    parser.add_argument('--sample_rate', type=int, required=True, help="Sample rate in Hz")
    parser.add_argument('--log_file', required=True, help="Log file path")
    parser.add_argument('--gpio_pins', type=int, nargs='*', help="GPIO pins for digital sensors")
    parser.add_argument('--channels', type=int, nargs='*', help="MCP3008 channels for analog sensors")
    parser.add_argument('--spi_speed', type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument('--sensor_ids', type=int, nargs='+', required=True, help="Sensor IDs")

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(message)s')

    log_queue = queue.Queue()
    sensors = []
    threads = []

    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(
            sensor_id=sensor_id,
            sensor_type=args.sensor_type,
            threshold=args.threshold,
            sample_rate=args.sample_rate,
            gpio_pins=args.gpio_pins,
            channels=args.channels,
            spi_speed=args.spi_speed,
            log_queue=log_queue
        )
        sensors.append(sensor)
        thread = threading.Thread(target=sensor.run)
        threads.append(thread)
        thread.start()

    def signal_handler(sig, frame):
        logging.info("Shutting down...")
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()
        logging.info("Shutdown complete.")
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    while True:
        try:
            while not log_queue.empty():
                message = log_queue.get()
                logging.info(message)
        except KeyboardInterrupt:
            signal_handler(None, None)

if __name__ == "__main__":
    main()

