import spidev
import time
import signal
import sys

class MCP3008:
    def __init__(self, bus=0, device=0):
        self.spi = spidev.SpiDev()
        self.bus = bus
        self.device = device
        self.open()

    def open(self):
        try:
            self.spi.open(self.bus, self.device)
            self.spi.max_speed_hz = 1350000
        except OSError as e:
            print(f"Error opening SPI bus: {e}")
            sys.exit(1)

    def close(self):
        try:
            self.spi.close()
        except OSError as e:
            print(f"Error closing SPI bus: {e}")

    def read_adc(self, channel):
        if channel < 0 or channel > 7:
            raise ValueError("Channel must be an integer between 0 and 7")

        adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def calculate_ppm(raw_value):
    voltage = (raw_value / 1023.0) * 3.3
    ppm = voltage * 200
    return ppm

def determine_alert_level(ppm):
    if ppm < 150:
        return "Safe"
    elif 150 <= ppm < 400:
