class BalanceBeamController:
    def __init__(self):
        self.sensor = DistanceSensor(
            trigger=23,
            echo=24,
            max_distance=100,
            pin_factory=PiGPIOFactory()
        )
        self.servo = AngularServo(25, min_angle=0, max_angle=50, pin_factory=PiGPIOFactory())
        self.pid = PID(0.5, 0.00, 0.4, setpoint=25)
        self.pid.output_limits = (0, 50)
        self.setpoint = 25
        self.tolerance = 3
        self.max_error = 25
        self.balance_time = 3
        self.consecutive_balances = 0
        self.running = True

        # Register signal handler for clean exit
        signal.signal(signal.SIGINT, self.signal_handler)

    def signal_handler(self, signum, frame):
        logging.info("SIGINT received, stopping controller.")
        self.running = False

    def run(self):
        try:
            while self.running:
                try:
                    distance = self.sensor.distance * 100  # Convert to cm
                    logging.info(f"Distance: {distance:.2f} cm")
                except Exception as e:
                    logging.error(f"Sensor read error: {e}")
                    distance = None

                if distance is not None:
                    error = self.setpoint - distance
                    logging.info(f"Error: {error:.2f} cm")

                    if abs(error) > self.max_error:
                        logging.warning("Error exceeds maximum allowed, skipping PID update.")
                        continue

                    try:
                        command = self.pid(error)
                        self.servo.value = command
                        logging.info(f"Servo command: {command:.2f} degrees")
                    except Exception as e:
                        logging.error(f"Servo write error: {e}")

                    if abs(error) <= self.tolerance:
                        self.consecutive_balances += 1
                        if self.consecutive_balances >= self.balance_time:
                            logging.info("Balance achieved, detaching servo.")
                            self.servo.detach()
                            self.running = False
                    else:
                        self.consecutive_balances = 0
                else:
                    self.consecutive_balances = 0

                time.sleep(0.1)
        finally:
            self.cleanup()

    def cleanup(self):
        try:
            self.servo.detach()
        except Exception as e:
            logging.error(f"Error detaching servo: {e}")

        try:
            self.sensor.close()
        except Exception as e:
            logging.error(f"Error closing sensor: {e}")

if __name__ == "__main__":
    controller = BalanceBeamController()
    try:
        controller.run()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        controller.cleanup()

