from busio import I2C
from adafruit_bmp280 import BMP280
from adafruit_bme280 import BME280
from adafruit_ms8607 import MS8607
from adafruit_bus_device.i2c_device import I2CDevice

# Configure logging
logging.basicConfig(filename='error.log', level=logging.ERROR, format='%(asctime)s %(message)s')

# Load configuration
config = {}
try:
    with open('config.txt', 'r') as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#'):
                key, value = line.split('=', 1)
                config[key.strip()] = value.strip()
except FileNotFoundError:
    logging.error("Configuration file 'config.txt' not found.")
    sys.exit(0)

# Default values
sensors = []
sampling_interval = int(config.get('Sampling_Interval_Seconds', 60))

# I2C setup
try:
    i2c = I2C(1, scl=2, sda=3)
except Exception as e:
    logging.error(f"I2C bus error: {e}")
    sys.exit(0)

# Sensor setup
def initialize_sensors():
    sensor_addresses = [0x76, 0x77, 0x78]
    sensor_types = {
        'BMP280': BMP280,
        'BME280': BME280,
        'MS8607': MS8607
    }
    sensor_ids = {
        'BMP280': 0x58,
        'BME280': 0x60
    }

    for i in range(1, 4):
        sensor_type = config.get(f'Sensor{i}_Type')
        sensor_address = int(config.get(f'Sensor{i}_Address', 0), 16)
        sensor_id = config.get(f'Sensor{i}_ID')

        if sensor_type and sensor_address in sensor_addresses:
            try:
                if sensor_type == 'MS8607' and sensor_address != 0x78:
                    continue
                if sensor_type in ['BMP280', 'BME280'] and sensor_address == 0x78:
                    continue

                i2c_device = I2CDevice(i2c, sensor_address)
                if sensor_type in sensor_types:
                    sensor = sensor_types[sensor_type](i2c_device)
                    if sensor_type in sensor_ids:
                        chip_id = sensor._device.read_u8(0xD0)
                        if chip_id != sensor_ids[sensor_type]:
                            logging.error(f"Invalid chip ID for {sensor_type} at address {sensor_address:#04x}.")
                            continue

                    sensors.append({
                        'type': sensor_type,
                        'id': sensor_id,
                        'sensor': sensor
                    })
            except Exception as e:
                logging.error(f"Failed to initialize {sensor_type} at address {sensor_address:#04x}: {e}")

    if not sensors:
        logging.error("No valid sensors found.")
        sys.exit(0)

# Database setup
def setup_database():
    try:
        conn = sqlite3.connect('wildlife_data.db')
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        ''')
        conn.commit()
        return conn
    except Exception as e:
        logging.error(f"Database error: {e}")
        sys.exit(0)

# Validate sensor data
def validate_data(pressure, temperature, humidity):
    if not (70000 <= pressure <= 110000):
        logging.warning(f"Invalid pressure reading: {pressure} Pa")
        return False
    if not (-20 <= temperature <= 50):
        logging.warning(f"Invalid temperature reading: {temperature} °C")
        return False
    if humidity is not None and not (0 <= humidity <= 100):
        logging.warning(f"Invalid humidity reading: {humidity} %RH")
        return False
    return True

# Read and store sensor data
def read_and_store_data(conn):
    cursor = conn.cursor()
    timestamp = datetime.utcnow().isoformat()
    for sensor_info in sensors:
        try:
            pressure = sensor_info['sensor'].pressure
            temperature = sensor_info['sensor'].temperature
            humidity = getattr(sensor_info['sensor'], 'humidity', None)

            if validate_data(pressure, temperature, humidity):
                cursor.execute('''
                    INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
                    VALUES (?, ?, ?, ?, ?, ?)
                ''', (timestamp, sensor_info['type'], sensor_info['id'], pressure, temperature, humidity))
                conn.commit()
        except Exception as e:
            logging.error(f"Error reading data from {sensor_info['type']} with ID {sensor_info['id']}: {e}")

# Graceful exit
def signal_handler(sig, frame):
    logging.info("Exiting gracefully...")
    if 'conn' in globals():
        conn.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

# Main loop
if __name__ == '__main__':
    initialize_sensors()
    conn = setup_database()

    try:
        while True:
            read_and_store_data(conn)
            sleep(sampling_interval)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if 'conn' in globals():
            conn.close()

