        raise ValueError("Input must be a real number.")

    sign = -1 if degrees_decimal < 0 else 1
    degrees_decimal = abs(degrees_decimal)

    degrees = int(degrees_decimal)
    minutes = int((degrees_decimal - degrees) * 60)
    seconds = (degrees_decimal - degrees - minutes / 60) * 3600

    return (sign * degrees, sign * minutes, sign * seconds)

def number_to_exif_rational(number: Real) -> Tuple[int, int]:
    if not isinstance(number, Real):
        raise ValueError("Input must be a real number.")

    try:
        fraction = Fraction(number).limit_denominator(1000)
    except Exception as e:
        raise ValueError("Cannot convert to fraction.") from e

    numerator, denominator = fraction.numerator, fraction.denominator

    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise TypeError("Numerator and denominator must be integers.")

    return (numerator, denominator)

# Example usage:
try:
    dms = degrees_decimal_to_dms(45.7625)
    print("DMS:", dms)

    exif_rational = number_to_exif_rational(45.7625)
    print("EXIF Rational:", exif_rational)
except (ValueError, TypeError) as e:
    print("Error:", e)
```

This code provides two utility functions with robust type checking and error handling. The `degrees_decimal_to_dms` function converts decimal degrees to degrees, minutes, and seconds, preserving the sign. The `number_to_exif_rational` function converts a real number to a rational representation suitable for EXIF metadata, with a denominator limited to 1000.

