        try:
            jpeg_bytes = self.get_frame()
            detected = MotionSensor().value
            return jpeg_bytes, detected
        except Exception as e:
            logging.error(f"Error in get_object_with_basic_motion_detection: {e}")
            return None, False

    def stop(self):
        if camera:
            camera.stop()
            camera.close()

def check_for_objects():
