            else:
                jpeg_bytes, detected = camera.get_object(config.classifier)

            if detected and config.send_email_notifications:
                current_time = time.time()
                if current_time - last_email_time >= config.email_send_interval:
                    try:
                        send_email(jpeg_bytes, config)
                        last_email_time = current_time
                    except Exception as e:
                        logging.error(f"Failed to send email: {e}")

            time.sleep(1)
        except Exception as e:
            logging.error(f"Error in check_for_objects: {e}")

@app.route('/')
def index():
    return render_template('index.html', config=config)

@app.route('/video_feed')
def video_feed():
    def generate():
        while not stop_event.is_set():
            frame = camera.get_frame()
            if frame:
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n')
    return Response(generate(), mimetype='multipart/x-mixed-replace; boundary=frame')

