import os
import time
import logging
import numpy as np
import matplotlib.pyplot as plt
from datetime import datetime
import csv
from gpiozero import Device
from smbus2 import SMBus, i2c_msg, SMBusWrapper
from smbus import SMBus as SMBusFallback
import errno

# Constants
I2C_ADDRESS = 0x69
I2C_BUS = 1
PIXEL_COUNT = 64
TEMP_THRESHOLD = 70.0
LOG_DIR = "/home/pi/thermal_logs"
LOG_FILE = os.path.join(LOG_DIR, "thermal_monitor_{}.log".format(datetime.now().strftime("%Y%m%d")))
CSV_FILE = os.path.join(LOG_DIR, "thermal_data.csv")
IMAGE_DIR = os.path.join(LOG_DIR, "thermal_image_{}.png")

# Setup logging
if not os.path.exists(LOG_DIR):
    os.makedirs(LOG_DIR)

logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s %(message)s')

def get_smbus():
    try:
        return SMBusWrapper(I2C_BUS)
    except Exception as e:
        logging.error("Failed to initialize SMBus2: {}".format(e))
        try:
            return SMBus(I2C_BUS)
        except Exception as e:
            logging.error("Failed to initialize SMBus: {}".format(e))
            raise RuntimeError("Failed to initialize I2C bus")

def check_sensor(bus):
    try:
        bus.write_byte(I2C_ADDRESS, 0x80)  # Reset command
        time.sleep(0.1)
        bus.read_byte(I2C_ADDRESS)  # Check if sensor responds
        return True
    except Exception as e:
        logging.error("Sensor check failed: {}".format(e))
        return False

def read_temperature(bus):
    try:
        data = i2c_msg.read(bus, I2C_ADDRESS, PIXEL_COUNT * 2)
        bus.i2c_rdwr(data)
        data = list(data)
        temperatures = np.array(data).reshape((8, 8, 2))
        return temperatures[:, :, 0] + (temperatures[:, :, 1] << 8)
    except Exception as e:
        logging.error("Failed to read temperature data: {}".format(e))
        return None

def save_heatmap(data, filename):
    try:
        plt.imshow(data, cmap='jet', interpolation='nearest')
        plt.colorbar()
        plt.savefig(filename)
        plt.close()
    except Exception as e:
        logging.error("Failed to save heatmap: {}".format(e))

def append_csv_data(timestamp, avg_temp, data):
    try:
        with open(CSV_FILE, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, avg_temp] + data.flatten().tolist())
    except Exception as e:
        logging.error("Failed to write to CSV: {}".format(e))

def main():
    try:
        bus = get_smbus()
        if not check_sensor(bus):
            raise RuntimeError("AMG8833 sensor not detected")

        logging.info("Sensor initialized successfully")

        if not os.path.exists(CSV_FILE):
            with open(CSV_FILE, 'w', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow(["Timestamp", "Average Temperature"] + ["Pixel_{}".format(i) for i in range(PIXEL_COUNT)])

        try:
            while True:
                start_time = time.time()
                temperatures = read_temperature(bus)
                if temperatures is not None:
                    avg_temp = np.mean(temperatures)
                    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                    logging.info("Average temperature: {:.2f}°C".format(avg_temp))

                    if avg_temp > TEMP_THRESHOLD:
                        print("Alert: Average temperature exceeded threshold!")
                        logging.warning("Average temperature exceeded threshold: {:.2f}°C".format(avg_temp))

                    save_heatmap(temperatures, IMAGE_DIR.format(timestamp))
                    append_csv_data(timestamp, avg_temp, temperatures)

                elapsed_time = time.time() - start_time
                sleep_time = max(1.0 - elapsed_time, 0)
                time.sleep(sleep_time)

        except KeyboardInterrupt:
            logging.info("Program terminated by user")
        finally:
            bus.close()
            logging.info("Resources released and program exited")

    except Exception as e:
        logging.error("An error occurred: {}".format(e))

if __name__ == "__main__":
    main()

