import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
from contextlib import contextmanager

# Signal handler to ensure clean exit
def signal_handler(sig, frame):
    print("Exiting gracefully...")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

@contextmanager
def managed_resources(camera, ser):
    try:
        yield
    finally:
        if camera.isOpened():
            camera.release()
        if ser and ser.is_open:
            ser.close()
        cv2.destroyAllWindows()

def find_serial_port():
    ports = list(serial.tools.list_ports.comports())
    for port in ports:
        if port.device == '/dev/ttyACM0':
            return port.device
    for port in ports:
        if 'USB' in port.device:
            return port.device
    return None

def main():
    # Initialize camera
    camera = cv2.VideoCapture(0)
    if not camera.isOpened():
        print("Error: Could not open video device.")
        return

    # Initialize serial
    serial_port = find_serial_port()
    ser = None
    if serial_port:
        try:
            ser = serial.Serial(serial_port, 9600, timeout=1)
        except serial.SerialException as e:
            print(f"Warning: Could not open serial port {serial_port}. Error: {e}")
            ser = None

    if not ser:
        print("Warning: No serial port available. Continuing in serial-disabled mode.")

    # Define ROI
    frame_width = int(camera.get(cv2.CAP_PROP_FRAME_WIDTH))
    frame_height = int(camera.get(cv2.CAP_PROP_FRAME_HEIGHT))
    roi_center_x = frame_width // 2
    roi_center_y = frame_height // 2
    roi_half_extent = 50
    roi_x1 = roi_center_x - roi_half_extent
    roi_y1 = roi_center_y - roi_half_extent
    roi_x2 = roi_center_x + roi_half_extent
    roi_y2 = roi_center_y + roi_half_extent

    tracking_enabled = False
    min_hsv = None
    max_hsv = None

    with managed_resources(camera, ser):
        while True:
            ret, frame = camera.read()
            if not ret:
                print("Error: Could not read frame.")
                break

            if tracking_enabled:
                roi = frame[roi_y1:roi_y2, roi_x1:roi_x2]
                hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
                mask = cv2.inRange(hsv_roi, min_hsv, max_hsv)
                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    if cv2.contourArea(contour) > 500:
                        x, y, w, h = cv2.boundingRect(contour)
                        cv2.rectangle(frame, (roi_x1 + x, roi_y1 + y), (roi_x1 + x + w, roi_y1 + y + h), (255, 0, 0), 2)
                        ball_center_x = roi_x1 + x + w // 2
                        ball_center_y = roi_y1 + y + h // 2

                        if ser:
                            try:
                                if ball_center_x > roi_center_x + roi_half_extent and ball_center_y > roi_center_y + roi_half_extent:
                                    ser.write(b'1')
                                elif ball_center_x > roi_center_x + roi_half_extent and ball_center_y < roi_center_y - roi_half_extent:
                                    ser.write(b'2')
                                elif ball_center_x < roi_center_x - roi_half_extent and ball_center_y > roi_center_y + roi_half_extent:
                                    ser.write(b'3')
                                elif ball_center_x < roi_center_x - roi_half_extent and ball_center_y < roi_center_y - roi_half_extent:
                                    ser.write(b'4')
                                elif abs(ball_center_x - roi_center_x) <= roi_half_extent and abs(ball_center_y - roi_center_y) <= roi_half_extent:
                                    ser.write(b'5')
                            except serial.SerialException as e:
                                print(f"Warning: Serial write error. Error: {e}")

            cv2.imshow("Frame", frame)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                roi = frame[roi_y1:roi_y2, roi_x1:roi_x2]
                hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
                min_hsv = np.min(hsv_roi, axis=(0, 1))
                max_hsv = np.max(hsv_roi, axis=(0, 1))
                tracking_enabled = True
            elif key == ord('o'):
                tracking_enabled = False
            elif key == 27:  # ESC key
                break

if __name__ == "__main__":
    main()

