                        cv2.rectangle(frame, (roi_x1 + x, roi_y1 + y), (roi_x1 + x + w, roi_y1 + y + h), (255, 0, 0), 2)
                        ball_center_x = roi_x1 + x + w // 2
                        ball_center_y = roi_y1 + y + h // 2

                        if ser:
                            try:
                                if ball_center_x > roi_center_x + roi_half_extent and ball_center_y > roi_center_y + roi_half_extent:
                                    ser.write(b'1')
                                elif ball_center_x > roi_center_x + roi_half_extent and ball_center_y < roi_center_y - roi_half_extent:
                                    ser.write(b'2')
                                elif ball_center_x < roi_center_x - roi_half_extent and ball_center_y > roi_center_y + roi_half_extent:
                                    ser.write(b'3')
                                elif ball_center_x < roi_center_x - roi_half_extent and ball_center_y < roi_center_y - roi_half_extent:
                                    ser.write(b'4')
                                elif abs(ball_center_x - roi_center_x) <= roi_half_extent and abs(ball_center_y - roi_center_y) <= roi_half_extent:
                                    ser.write(b'5')
                            except serial.SerialException as e:
                                print(f"Warning: Serial write error. Error: {e}")

            cv2.imshow("Frame", frame)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                roi = frame[roi_y1:roi_y2, roi_x1:roi_x2]
                hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
                min_hsv = np.min(hsv_roi, axis=(0, 1))
                max_hsv = np.max(hsv_roi, axis=(0, 1))
                tracking_enabled = True
            elif key == ord('o'):
                tracking_enabled = False
            elif key == 27:  # ESC key
                break

if __name__ == "__main__":
