        time.sleep(0.01)  # Ensure clean start

        trigger.on()
        time.sleep(0.00001)  # 10 microseconds
        trigger.off()

        start_time = time.time()
        echo.wait_for_active(timeout=0.05)  # 50 ms timeout for echo start
        if not echo.is_active:
            return None

        pulse_start = time.time()
        echo.wait_for_inactive(timeout=0.05)  # 50 ms timeout for echo end
        pulse_duration = time.time() - pulse_start

