                    if level is not None:
                        water_levels.append(level)
                        logging.info(f"Water level: {level:.2f} cm")

                if water_levels:
                    average_level = statistics.mean(water_levels)
                    logging.info(f"Average water level: {average_level:.2f} cm")
                    check_alerts(average_level)
                else:
                    logging.warning("No valid sensor readings")

                time.sleep(5)
            except Exception as e:
                logging.error(f"Unexpected error: {e}")

if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        logging.info("Program exited cleanly")
    except Exception as e:
        logging.error(f"Fatal error: {e}")

