import RPi.GPIO as GPIO
import time
import signal
import sys
import random
import logging
from datetime import datetime
from picamera2 import Picamera2
import speech_recognition as sr
from adafruit_dht import DHT11, DHTDevice
from adafruit_dht import InvalidChecksumError, SensorTimeoutError

# Setup logging
logging.basicConfig(level=logging.INFO)

# GPIO setup
GPIO_PIN_LIGHTS = 17
GPIO_PIN_TEMPERATURE = 4
SIMULATED_GPIO = False

def initialize_gpio():
    global SIMULATED_GPIO
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO_PIN_LIGHTS, GPIO.OUT)
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        SIMULATED_GPIO = True

def turn_lights_on():
    if SIMULATED_GPIO:
        logging.info("Simulating turning lights on.")
    else:
        try:
            GPIO.output(GPIO_PIN_LIGHTS, GPIO.HIGH)
            logging.info("Lights turned on.")
        except Exception as e:
            logging.error(f"Failed to turn lights on: {e}")

def turn_lights_off():
    if SIMULATED_GPIO:
        logging.info("Simulating turning lights off.")
    else:
        try:
            GPIO.output(GPIO_PIN_LIGHTS, GPIO.LOW)
            logging.info("Lights turned off.")
        except Exception as e:
            logging.error(f"Failed to turn lights off: {e}")

def read_temperature():
    if SIMULATED_GPIO:
        return random.uniform(15, 35)

    try:
        dht_device = DHTDevice(DHT11, GPIO_PIN_TEMPERATURE)
        dht_device.measure()
        temperature = dht_device.temperature
        logging.info(f"Temperature: {temperature}°C")
        return temperature
    except (InvalidChecksumError, SensorTimeoutError) as e:
        logging.error(f"Sensor error: {e}")
    except Exception as e:
        logging.error(f"Failed to read temperature: {e}")

    return random.uniform(15, 35)

def capture_image():
    try:
        with Picamera2() as camera:
            camera.resolution = (640, 480)
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture(filename)
            logging.info(f"Image captured: {filename}")
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")

def listen_for_commands():
    recognizer = sr.Recognizer()
    microphone = sr.Microphone()

    try:
        with microphone as source:
            recognizer.adjust_for_ambient_noise(source)
            logging.info("Listening for commands...")
            audio = recognizer.listen(source, timeout=5)
            command = recognizer.recognize_google(audio).lower()
            logging.info(f"Recognized command: {command}")

            if "greenhouse" in command:
                if "turn on the lights" in command:
                    turn_lights_on()
                elif "turn off the lights" in command:
                    turn_lights_off()
                elif "what is the temperature" in command:
                    temp = read_temperature()
                    logging.info(f"The temperature is {temp}°C")
                elif "take a picture" in command:
                    capture_image()
                else:
                    logging.info("Unknown command.")
    except sr.UnknownValueError:
        logging.error("Could not understand audio.")
    except sr.RequestError as e:
        logging.error(f"Could not request results; {e}")
    except Exception as e:
        logging.error(f"Error during voice recognition: {e}")

def cleanup():
    if not SIMULATED_GPIO:
        GPIO.cleanup()
    logging.info("Cleaned up resources.")

def signal_handler(sig, frame):
    logging.info("Exiting gracefully...")
    cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    initialize_gpio()
    try:
        while True:
            listen_for_commands()
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

