import time
import signal
import logging
from gpiozero import PWMOutputDevice
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
FAN_PIN = 17
CPU_TEMP_PATH = '/sys/class/thermal/thermal_zone0/temp'
DEFAULT_PWM = 1.0
THRESHOLDS = [65.0, 55.0, 50.0, 45.0]
PWM_VALUES = [1.0, 0.8, 0.6, 0.4]

# Validate configuration
if len(THRESHOLDS) != len(PWM_VALUES):
    raise ValueError("Thresholds and PWM values lists must have the same length.")
if not all(0.0 <= pwm <= 1.0 for pwm in PWM_VALUES):
    raise ValueError("All PWM values must be within the range [0.0, 1.0].")

# Context manager for PWMOutputDevice
@contextmanager
def pwm_device(pin):
    try:
        pwm = PWMOutputDevice(pin)
        yield pwm
    except Exception as e:
        logging.error(f"Error initializing PWMOutputDevice: {e}")
        raise
    finally:
        try:
            pwm.close()
            logging.info("PWMOutputDevice closed successfully.")
        except Exception as e:
            logging.error(f"Error closing PWMOutputDevice: {e}")

def read_cpu_temperature():
    try:
        with open(CPU_TEMP_PATH, 'r') as f:
            temp_millidegrees = int(f.read().strip())
            return temp_millidegrees / 1000.0
    except Exception as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None

def get_target_pwm(temperature):
    for threshold, pwm in zip(THRESHOLDS, PWM_VALUES):
        if temperature > threshold:
            return pwm
    return PWM_VALUES[-1]

def signal_handler(signum, frame):
    logging.info("Signal received, shutting down...")
    cleanup()

def cleanup():
    global pwm
    try:
        pwm.value = DEFAULT_PWM
        logging.info("Fan set to default PWM value on shutdown.")
    except Exception as e:
        logging.error(f"Error setting default PWM on shutdown: {e}")

def main():
    global pwm
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with pwm_device(FAN_PIN) as pwm:
            logging.info("PWMOutputDevice initialized successfully.")
            pwm.value = DEFAULT_PWM
            logging.info("Fan set to default PWM value on startup.")

            while True:
                temperature = read_cpu_temperature()
                if temperature is not None:
                    target_pwm = get_target_pwm(temperature)
                    logging.info(f"Current temperature: {temperature:.2f}°C, Target PWM: {target_pwm:.2f}")
                    try:
                        pwm.value = target_pwm
                    except Exception as e:
                        logging.error(f"Error setting PWM value: {e}")
                else:
                    logging.warning("Using default PWM value due to temperature read error.")
                    pwm.value = DEFAULT_PWM

                time.sleep(5)

    except Exception as e:
        logging.error(f"Program terminated due to error: {e}")
        exit(1)

if __name__ == "__main__":
    main()

