import sys
import serial
import serial.serialutil
import logging
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@contextmanager
def open_serial_port(port, baudrate):
    ser = None
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        logging.info(f"Opened serial port {port} at {baudrate} baud.")
        yield ser
    except serial.serialutil.SerialException as e:
        logging.error(f"SerialException: {e}")
        raise
    finally:
        if ser and ser.is_open:
            ser.close()
            logging.info(f"Closed serial port {port}.")

def main():
    port = '/dev/rfcomm4'
    baudrate = 38400

    try:
        with open_serial_port(port, baudrate) as ser:
            while True:
                try:
                    user_input = input("Enter text to send (type 'q' to quit): ")
                    if user_input.lower() == 'q':
                        break

                    message = f"X{user_input}"
                    try:
                        ser.write(message.encode('utf-8'))
                        logging.info(f"Sent: {message} ({len(message)} bytes)")
                    except serial.serialutil.SerialException as e:
                        logging.error(f"SerialException during write: {e}")
                except KeyboardInterrupt:
                    logging.info("Interrupted by user, exiting.")
                    break
    except serial.serialutil.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

