import numpy as np
import signal
import threading
import websockets
from picamera2 import Picamera2, Config
from websockets.exceptions import ConnectionClosed

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class WebSocketHandler:
    def __init__(self):
        self._connections = set()
        self._lock = threading.Lock()

    async def register(self, websocket):
        async with self._lock:
            self._connections.add(websocket)

    async def unregister(self, websocket):
        async with self._lock:
            self._connections.remove(websocket)

    def has_connections(self):
        with self._lock:
            return len(self._connections) > 0

    async def broadcast(self, data):
        if not self.has_connections():
            return

        async with self._lock:
            connections = list(self._connections)

        for websocket in connections:
            try:
                await websocket.send(data)
            except ConnectionClosed:
                await self.unregister(websocket)

class CameraStreamer:
    def __init__(self, detect_motion_function):
        self.detect_motion_function = detect_motion_function
        self._stop_event = threading.Event()
        self._frame_lock = threading.Lock()
        self._prev_frame = None
        self._ws_handler = WebSocketHandler()
        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(target=self._run_loop, daemon=True)
        self._thread.start()

    def _run_loop(self):
        asyncio.set_event_loop(self._loop)
        self._loop.run_forever()

    async def _websocket_handler(self, websocket, path):
        await self._ws_handler.register(websocket)
        try:
            async for _ in websocket:
                pass
        finally:
            await self._ws_handler.unregister(websocket)

    def _start_camera(self):
        try:
            self._camera = Picamera2()
            config = Config()
            config.configure(output={
                'preview': {'size': (640, 480), 'format': 'RGB888'},
                'main': {'size': (640, 480), 'format': 'jpeg', 'compression_level': 10}
            })
            self._camera.configure(config)
            self._camera.start_recording(self._on_frame, format='h264', splitter_port=2)
        except Exception as e:
            logger.error(f"Camera initialization error: {e}")
            self._stop_event.set()

    def _on_frame(self, camera, data, frame):
        if self._stop_event.is_set():
            return

        try:
            with self._frame_lock:
                if self._prev_frame is not None:
                    self._detect_motion(self._prev_frame, frame)
                self._prev_frame = frame

            if self._is_jpeg_frame(data):
                jpeg_data = self._extract_jpeg(data)
                if jpeg_data:
                    asyncio.run_coroutine_threadsafe(
                        self._ws_handler.broadcast(jpeg_data), self._loop
                    )
        except Exception as e:
            logger.error(f"Frame processing error: {e}")

    def _is_jpeg_frame(self, data):
        return data.startswith(b'\xff\xd8')

    def _extract_jpeg(self, data):
        start = data.find(b'\xff\xd8')
        end = data.find(b'\xff\xd9', start)
        if start != -1 and end != -1:
            return data[start:end + 2]
        return None

    def _detect_motion(self, prev_frame, curr_frame):
        prev_np = cv2.imdecode(np.frombuffer(prev_frame, np.uint8), cv2.IMREAD_COLOR)
        curr_np = cv2.imdecode(np.frombuffer(curr_frame, np.uint8), cv2.IMREAD_COLOR)
        if prev_np is not None and curr_np is not None:
            self.detect_motion_function(prev_np, curr_np)

    def start(self):
        self._start_camera()
        start_server = websockets.serve(self._websocket_handler, "0.0.0.0", 8765)
        self._loop.run_until_complete(start_server)

    def stop(self):
        self._stop_event.set()
        self._camera.stop_recording(splitter_port=2)
        self._camera.close()
        self._loop.call_soon_threadsafe(self._loop.stop)
        self._thread.join()

def detect_motion(prev_frame, curr_frame):
    # Example motion detection logic
    diff = cv2.absdiff(prev_frame, curr_frame)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
    contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if len(contours) > 0:
        logger.info("Motion detected")

def signal_handler(streamer, signum, frame):
    logger.info(f"Received signal {signum}, stopping...")
    streamer.stop()

if __name__ == "__main__":
    streamer = CameraStreamer(detect_motion)
    signal.signal(signal.SIGINT, lambda s, f: signal_handler(streamer, s, f))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(streamer, s, f))
    try:
        streamer.start()
    except Exception as e:
        logger.error(f"Error starting streamer: {e}")
        streamer.stop()

