import time
import signal
import sys
from gpiozero import CPUTemperature
from smbus2 import SMBus, SMBusWrapper
from adafruit_amg88xx import AMG88XX
import picamera2
import matplotlib.pyplot as plt
from logging.handlers import RotatingFileHandler

# Default configuration
default_config = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False
}

# Load configuration
config = default_config.copy()
try:
    with open('config.json', 'r') as f:
        config.update(json.load(f))
except (FileNotFoundError, json.JSONDecodeError) as e:
    logging.error(f"Config file error: {e}. Using default configuration.")

# Setup logging
logger = logging.getLogger("BeehiveMonitor")
logger.setLevel(logging.DEBUG)
handler = RotatingFileHandler(
    config["logging_file_path"],
    maxBytes=config["log_max_size"],
    backupCount=1
)
formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)

# Global variables
thermal_data = np.zeros((300, 8, 8))
frame_index = 0
stop_event = threading.Event()
camera = None

def initialize_i2c():
    try:
        return SMBusWrapper(1)
    except Exception as e:
        logger.error(f"Failed to open I2C bus: {e}")
        sys.exit(1)

def initialize_sensor(i2c):
    for attempt in range(3):
        try:
            return AMG88XX(i2c, address=0x69)
        except Exception as e:
            logger.warning(f"Sensor initialization attempt {attempt + 1} failed: {e}")
            time.sleep(2)
    logger.error("Failed to initialize sensor after 3 attempts.")
    sys.exit(1)

def initialize_camera():
    global camera
    try:
        camera = picamera2.PiCamera2()
        camera.configure(output='still')
    except Exception as e:
        logger.warning(f"Camera initialization failed: {e}")

def capture_image():
    try:
        camera.capture('/tmp/beehive_capture.jpg')
        logger.info("Image captured.")
    except Exception as e:
        logger.error(f"Failed to capture image: {e}")

def sample_thermal_data(sensor):
    global frame_index
    while not stop_event.is_set():
        try:
            frame = sensor.pixels
            thermal_data[frame_index % 300] = frame
            frame_index += 1
            time.sleep(1 / config["sampling_rate"])
        except Exception as e:
            logger.error(f"Error reading thermal data: {e}")

def detect_motion():
    global frame_index
    while not stop_event.is_set():
        try:
            if frame_index < 2:
                time.sleep(0.1)
                continue

            current_frame = thermal_data[frame_index % 300]
            previous_frame = thermal_data[(frame_index - 1) % 300]
            diff = np.abs(current_frame - previous_frame).mean()

            if diff > config["motion_detection_threshold"] and config["enable_camera"]:
                logger.info("Motion detected.")
                capture_image()

            time.sleep(0.1)
        except Exception as e:
            logger.error(f"Error in motion detection: {e}")

def render_heatmap():
    while not stop_event.is_set():
        try:
            plt.imshow(thermal_data[frame_index % 300], cmap='jet', interpolation='nearest')
            plt.colorbar()
            plt.title(time.strftime("%Y-%m-%d %H:%M:%S"))
            plt.pause(0.1)
            plt.clf()
            time.sleep(5 - 0.1)
        except Exception as e:
            logger.error(f"Error rendering heatmap: {e}")

def cleanup():
    stop_event.set()
    if camera:
        camera.close()
    logger.info("Cleanup complete.")

def signal_handler(sig, frame):
    logger.info("Signal received, shutting down.")
    cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    i2c = initialize_i2c()
    sensor = initialize_sensor(i2c)
    if config["enable_camera"]:
        initialize_camera()

    threads = [
        threading.Thread(target=sample_thermal_data, args=(sensor,)),
        threading.Thread(target=detect_motion),
        threading.Thread(target=render_heatmap)
    ]

    for thread in threads:
        thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()
        i2c.close()
        for handler in logger.handlers:
            handler.close()
        logger.info("Program exited cleanly.")

if __name__ == "__main__":
    main()

