import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2
from picamera2.encoders import MjpegEncoder
from picamera2.outputs import OutputStream

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class CameraStreamBuffer:
    def __init__(self, camera: Picamera2):
        self.camera = camera
        self.buffer = io.BytesIO()
        self.current_frame_complete = False

    def write(self, data: bytes):
        try:
            self.buffer.write(data)
            metadata = self.camera.current_configuration()
            if metadata and metadata.get('encode') == 'h264':
                frame_type = metadata.get('frame_type', 0)
                if frame_type != 1:  # Not an I-frame
                    self.flush()
        except IOError as e:
            logger.error(f"IOError in CameraStreamBuffer.write: {e}")

    def flush(self):
        try:
            self.buffer.seek(0)
            output = self.buffer.read()
            self.buffer = io.BytesIO()
            # Here you would send `output` to your desired output sink
            logger.info("Flushed non-I-frame data")
        except Exception as e:
            logger.error(f"Error flushing buffer: {e}")

class MotionDetectionBuffer:
    def __init__(self, callback):
        self.callback = callback
        self.buffer = io.BytesIO()
        self.previous_frame = None

    def write(self, data: bytes):
        try:
            self.buffer.write(data)
            if data.startswith(b'\xff\xd8'):  # Start of Image (SOI) marker
                if self.previous_frame is not None:
                    self.process_frame()
                self.buffer = io.BytesIO()  # Reset buffer for new frame
                self.buffer.write(data)  # Start new frame with SOI marker
            else:
                self.buffer.write(data)
