signal.signal(signal.SIGTERM, signal_handler)

def read_cpu_temperature():
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            temp_milli = f.read().strip()
            temp_celsius = int(temp_milli) / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print("Error: CPU temperature file not found.")
    except PermissionError:
        print("Error: Permission denied when accessing CPU temperature file.")
    return None

def initialize_i2c_bus():
    try:
        with SMBusWrapper(I2C_BUS_NUMBER) as bus:
            # Attempt to read from the OLED address to check if it's available
            try:
                read = i2c_msg.read(OLED_ADDRESS, 1)
                bus.i2c_rdwr(read)
