import time
import logging
import subprocess
from datetime import datetime
from gpiozero import InputDevice
from random import uniform

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
LIGHT_PIN = 17
TEMP_PIN = 4
DAY_START = 6
DAY_END = 18

def setup_gpio():
    try:
        light_sensor = InputDevice(LIGHT_PIN, pull_up=False)
        temp_sensor = InputDevice(TEMP_PIN, pull_up=False)
        logging.info("GPIO initialized successfully.")
        return light_sensor, temp_sensor
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        raise

def simulate_light_level():
    try:
        current_hour = datetime.now().hour
        if DAY_START <= current_hour < DAY_END:
            return uniform(600, 1000)
        else:
            return uniform(100, 300)
    except Exception as e:
        logging.error(f"Error simulating light level: {e}")
        return 0

def simulate_temperature():
    try:
        return uniform(20, 30)
    except Exception as e:
        logging.error(f"Error simulating temperature: {e}")
        return 0

def simulate_voltage_current(light_level):
    try:
        if light_level > 300:
            voltage = uniform(11.5, 12.5)
            current = uniform(1.5, 2.5)
        else:
            voltage = uniform(10.0, 11.0)
            current = uniform(0.5, 1.0)
        return voltage, current
    except Exception as e:
        logging.error(f"Error simulating voltage/current: {e}")
        return 0, 0

def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=2)
        if result.returncode == 0:
            temp_str = result.stdout.strip()
            temp_value = float(temp_str.split('=')[1].replace("'C", ''))
            return temp_value
        else:
            logging.warning("vcgencmd failed to execute.")
            return None
    except FileNotFoundError:
        logging.warning("vcgencmd command not found.")
        return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

def log_data(light, temp, voltage, current, pi_temp):
    pi_temp_str = f"{pi_temp}°C" if pi_temp is not None else "N/A"
    logging.info(f"Light: {light} lux, Temp: {temp}°C, Voltage: {voltage}V, Current: {current}A, Pi Temp: {pi_temp_str}")

def check_thresholds(light, temp, pi_temp):
    if light < 300:
        logging.warning("Possible solar panel performance issues: Light below 300 lux.")
    if temp > 35:
        logging.warning("Simulated cooling-system activation: Temperature exceeds 35°C.")
    if pi_temp is not None and pi_temp > 75:
        logging.critical("Simulated system shutdown: Pi internal temperature exceeds 75°C.")

def main():
    try:
        light_sensor, temp_sensor = setup_gpio()
        while True:
            light_level = simulate_light_level()
            temp_level = simulate_temperature()
            voltage, current = simulate_voltage_current(light_level)
            pi_temp = read_pi_temperature()

            log_data(light_level, temp_level, voltage, current, pi_temp)
            check_thresholds(light_level, temp_level, pi_temp)

            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        light_sensor.close()
        temp_sensor.close()
        logging.info("GPIO devices closed.")

if __name__ == '__main__':
    main()

