import smbus2
import time
import logging
from crccheck.crc import Crc8

class DHT20Sensor:
    def __init__(self):
        self.bus = None
        self.address = 0x38
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.DEBUG)
        handler = logging.StreamHandler()
        handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
        self.logger.addHandler(handler)

        try:
            self.bus = smbus2.SMBus(1)
            time.sleep(0.5)  # Wait for power stabilization
            status = self.bus.read_byte_data(self.address, 0x71)
            if (status & 0x18) != 0x18:
                self.logger.error("Status check failed: bits 3 and 4 are not set.")
                return False
        except Exception as e:
            self.logger.error(f"Failed to open I2C bus or read status: {e}")
            return False

        return True

    def get_temperature_and_humidity(self):
        max_retries = 5
        for attempt in range(max_retries):
            try:
                self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
                start_time = time.time()
                while True:
                    status = self.bus.read_byte_data(self.address, 0x71)
                    if not (status & 0x80):  # Bit 7 is clear
                        break
                    if time.time() - start_time > 0.1:
                        self.logger.warning("Measurement timeout, retrying...")
                        break
                else:
                    continue

                data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
                raw_H = (data[1] << 16) | (data[2] << 8) | data[3]
                raw_T = ((data[3] & 0xF0) << 16) | (data[4] << 8) | data[5]
                crc = data[6]

                if not self.verify_crc(data[:6], crc):
                    self.logger.warning("CRC check failed, retrying...")
                    continue

                temperature = raw_T / 5242.88 - 50
                humidity = raw_H / 1048576 * 100
                return temperature, humidity, False

            except Exception as e:
                self.logger.error(f"Error during measurement: {e}")

            time.sleep(2)  # Delay before retry

        self.logger.error("Failed to get valid temperature and humidity after retries.")
        return None, None, True

    def verify_crc(self, data, crc):
        crc_calculator = Crc8(poly=0x31, init_value=0xFF)
        calculated_crc = crc_calculator.calc(bytes(data))
        return calculated_crc == crc

    def cleanup(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                self.logger.error(f"Error closing I2C bus: {e}")

    def __del__(self):
        self.cleanup()

