                return None, None

        # Read 40 bits
        data = []
        for _ in range(5):
            bits = []
            for _ in range(8):
                start_time = time.time()
                while GPIO.input(DHT_PIN) == GPIO.LOW:
                    if time.time() - start_time > DHT_TIMEOUT:
                        return None, None

                start_time = time.time()
                while GPIO.input(DHT_PIN) == GPIO.HIGH:
                    if time.time() - start_time > DHT_TIMEOUT:
                        return None, None

                pulse_width = time.time() - start_time
                bits.append(1 if pulse_width > 0.00004 else 0)

            data.append(bits)

        # Convert bits to bytes
        humidity = (data[0][0] << 7) | (data[0][1] << 6) | (data[0][2] << 5) | (data[0][3] << 4) | (data[0][4] << 3) | (data[0][5] << 2) | (data[0][6] << 1) | data[0][7]
        humidity_decimal = (data[1][0] << 7) | (data[1][1] << 6) | (data[1][2] << 5) | (data[1][3] << 4) | (data[1][4] << 3) | (data[1][5] << 2) | (data[1][6] << 1) | data[1][7]
        temperature = (data[2][0] << 7) | (data[2][1] << 6) | (data[2][2] << 5) | (data[2][3] << 4) | (data[2][4] << 3) | (data[2][5] << 2) | (data[2][6] << 1) | data[2][7]
        temperature_decimal = (data[3][0] << 7) | (data[3][1] << 6) | (data[3][2] << 5) | (data[3][3] << 4) | (data[3][4] << 3) | (data[3][5] << 2) | (data[3][6] << 1) | data[3][7]
        checksum = data[4][0] << 7 | data[4][1] << 6 | data[4][2] << 5 | data[4][3] << 4 | data[4][4] << 3 | data[4][5] << 2 | data[4][6] << 1 | data[4][7]

        # Validate checksum
        if checksum != ((humidity & 0xFF) + (humidity_decimal & 0xFF) + (temperature & 0xFF) + (temperature_decimal & 0xFF)) & 0xFF:
            return None, None

        # Calculate temperature and humidity
        humidity_value = humidity + humidity_decimal / 10.0
        if temperature & 0x80:  # Negative temperature
            temperature_value = -(temperature & 0x7F) - temperature_decimal / 10.0
        else:
            temperature_value = temperature + temperature_decimal / 10.0

        return temperature_value, humidity_value

    except Exception as e:
        print(f"Error reading DHT22: {e}")
        return None, None

def log_data(temperature, humidity):
    try:
        with open("humidity_log.txt", "a") as log_file:
            timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            log_file.write(f"{timestamp}, {temperature}, {humidity}\n")
    except Exception as e:
        print(f"Error logging data: {e}")

def main():
    if not setup_gpio():
        return

    try:
        while True:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature} C, Humidity: {humidity} %")
                log_data(temperature, humidity)
            else:
                print("Failed to read from DHT22 sensor.")
            time.sleep(10)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()
