import smbus2
import logging
import signal
import sys
import time

class DHT20Sensor:
    def __init__(self):
        self.bus = None
        self.crc_error = False
        self.setup_logging()
        self.setup_signal_handlers()
        try:
            self.bus = smbus2.SMBus(1)
            self.verify_sensor()
        except Exception as e:
            logging.error(f"Initialization error: {e}")
            self.bus = None

    def setup_logging(self):
        logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, exiting.")
        self.cleanup()
        sys.exit(0)

    def cleanup(self):
        if self.bus:
            self.bus.close()
            logging.info("I2C bus closed.")

    def verify_sensor(self):
        try:
            status = self.bus.read_byte_data(0x38, 0x71)
            if status is None:
                raise IOError("Failed to read status register.")
        except Exception as e:
            logging.error(f"Sensor verification failed: {e}")
            self.bus = None

    def measure(self):
        if not self.bus:
            logging.error("I2C bus not initialized.")
            return None, None, True

        try:
            self.bus.write_i2c_block_data(0x38, 0xAC, [0x33, 0x00])
            start_time = time.time()
            while time.time() - start_time < 0.1:
                status = self.bus.read_byte_data(0x38, 0x71)
                if status is None:
                    raise IOError("Failed to read status register during measurement.")
                if not (status & 0x80):
                    break
                time.sleep(0.01)
            else:
                logging.error("Measurement timeout.")
                return None, None, True

            data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
            if len(data) != 7:
                logging.error("Failed to read data from sensor.")
                return None, None, True

            crc = self.calculate_crc(data[:6])
            if crc != data[6]:
                logging.error("CRC check failed.")
                self.crc_error = True
                return None, None, True

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]

            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return temperature, humidity, self.crc_error

        except Exception as e:
            logging.error(f"Measurement error: {e}")
            return None, None, True

    def calculate_crc(self, data):
        crc = 0xFF
        polynomial = 0x31
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ polynomial
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def __del__(self):
        self.cleanup()

if __name__ == "__main__":
    sensor = DHT20Sensor()
    temperature, humidity, crc_error = sensor.measure()
    if crc_error:
        print("Measurement failed due to CRC error.")
    elif temperature is None or humidity is None:
        print("Measurement failed.")
    else:
        print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %")

