import time
import signal
import sys
import RPi.GPIO as GPIO
from adafruit_dht import DHT11
import board
import busio

# Setup DHT11 sensor
dht_pin = board.D4
dht_sensor = DHT11(dht_pin)

# Setup RGB LED strip
led_pins = {'red': 17, 'green': 27, 'blue': 22}
led_pwm = {color: GPIO.PWM(pin, 100) for color, pin in led_pins.items()}

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    for pwm in led_pwm.values():
        pwm.start(0)

def cleanup_gpio():
    for pwm in led_pwm.values():
        pwm.stop()
    GPIO.cleanup()

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    cleanup_gpio()
    sys.exit(0)

def map_temperature_to_color(temperature):
    if temperature < 20:
        return 'blue'
    elif 20 <= temperature <= 25:
        return 'green'
    else:
        return 'red'

def set_led_color(color):
    for col, pwm in led_pwm.items():
        duty_cycle = 100 if col == color else 0
        pwm.ChangeDutyCycle(duty_cycle)

def read_temperature():
    try:
        temperature = dht_sensor.temperature
        return temperature
    except RuntimeError as e:
        print(f"Failed to read temperature: {e}")
        return None

def main():
    setup_gpio()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    last_color = None

    try:
        while True:
            temperature = read_temperature()
            if temperature is not None:
                color = map_temperature_to_color(temperature)
                if color != last_color:
                    set_led_color(color)
                    last_color = color
            else:
                if last_color is not None:
                    print("Retrying temperature read...")
                    time.sleep(0.5)  # Short backoff before retrying

            time.sleep(1)  # Sample every 1 second

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

