import argparse
import json
import logging
import socket
import sys
from datetime import datetime
from gpiozero import OutputDevice
from contextlib import closing

# Setup argument parser
parser = argparse.ArgumentParser(description='Raspberry Pi Hydroponics Controller')
parser.add_argument('--relay_pin', type=int, default=17, help='GPIO pin for relay (default: 17)')
parser.add_argument('--dht_pin', type=int, default=4, help='GPIO pin for DHT11 (default: 4)')
parser.add_argument('--port', type=int, default=12345, help='TCP port to listen on (default: 12345)')
parser.add_argument('--allowed_ip', type=str, default='192.168.1.100', help='Allowed IP address (default: 192.168.1.100)')
parser.add_argument('--log_file', type=str, default='hydroponics.log', help='Log file path (default: hydroponics.log)')
args = parser.parse_args()

# Setup logging
logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(message)s')

# Initialize GPIO
try:
    relay = OutputDevice(args.relay_pin, initial_value=False)
except Exception as e:
    logging.error(f"Failed to initialize GPIO: {e}")
    sys.exit(1)

def set_pump_state(state):
    try:
        if state == "on":
            relay.on()
            logging.info("Pump turned ON")
        elif state == "off":
            relay.off()
            logging.info("Pump turned OFF")
    except Exception as e:
        logging.error(f"Failed to set pump state: {e}")

def get_status():
    return json.dumps({"pump": "on" if relay.is_active else "off", "temperature": 25.0})

def handle_client_connection(client_socket):
    try:
        request = client_socket.recv(1024).decode('utf-8')
        logging.info(f"Received request: {request}")
        try:
            command = json.loads(request)
            if command.get("command") == "pump_on":
                set_pump_state("on")
                response = json.dumps({"status": "pump turned on"})
            elif command.get("command") == "pump_off":
                set_pump_state("off")
                response = json.dumps({"status": "pump turned off"})
            elif command.get("command") == "get_status":
                response = get_status()
            else:
                response = json.dumps({"error": "Invalid command"})
        except json.JSONDecodeError:
            response = json.dumps({"error": "Invalid JSON"})

        client_socket.send(response.encode('utf-8'))
        logging.info(f"Sent response: {response}")
    except Exception as e:
        logging.error(f"Error handling client connection: {e}")
    finally:
        client_socket.close()
        logging.info("Client disconnected")

def start_server():
    with closing(socket.socket(socket.AF_INET, socket.SOCK_STREAM)) as server_socket:
        server_socket.bind(('', args.port))
        server_socket.listen(1)
        logging.info(f"Server listening on port {args.port}")

        while True:
            try:
                client_socket, addr = server_socket.accept()
                if addr[0] != args.allowed_ip:
                    logging.warning(f"Unauthorized connection attempt from {addr[0]}")
                    client_socket.close()
                    continue
                logging.info(f"Accepted connection from {addr[0]}")
                handle_client_connection(client_socket)
            except Exception as e:
                logging.error(f"Socket error: {e}")

def cleanup():
    relay.close()
    logging.info("GPIO resources released")

try:
    start_server()
except KeyboardInterrupt:
    logging.info("Server shutdown by user")
finally:
    cleanup()

