PWM_FREQUENCY = 50
DUTY_CYCLE_MAP = {0: 2.5, 90: 7.5, 180: 12.5}

# Logging setup
logging.basicConfig(filename='greenhouse_vent.log', level=logging.INFO, 
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Context manager for GPIO setup and cleanup
@contextmanager
def gpio_setup():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        servo1 = GPIO.PWM(SERVO_PIN_1, PWM_FREQUENCY)
        servo2 = GPIO.PWM(SERVO_PIN_2, PWM_FREQUENCY)
        servo1.start(0)
        servo2.start(0)
        yield servo1, servo2
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise
    finally:
        servo1.stop()
        servo2.stop()
        GPIO.cleanup()

def duty_cycle_for_angle(angle):
    """Calculate duty cycle for a given angle using linear interpolation."""
    if angle <= 0:
        return DUTY_CYCLE_MAP[0]
    elif angle >= 180:
        return DUTY_CYCLE_MAP[180]
    else:
        return DUTY_CYCLE_MAP[0] + (DUTY_CYCLE_MAP[180] - DUTY_CYCLE_MAP[0]) * (angle / 180)

def move_servo(servo, target_angle, current_angle):
    """Move servo smoothly from current_angle to target_angle."""
    step = 5 if target_angle > current_angle else -5
    for angle in range(current_angle, target_angle + step, step):
        duty_cycle = duty_cycle_for_angle(angle)
        servo.ChangeDutyCycle(duty_cycle)
        logging.info(f"Moving servo to {angle}° with duty cycle {duty_cycle}%")
        time.sleep(0.1)

def simulate_temperature():
    """Simulate a temperature reading between 15°C and 35°C."""
    return random.uniform(15, 35)

def determine_servo_angle(temperature):
    """Determine servo angle based on temperature."""
    if temperature < 20:
        return 0
    elif 20 <= temperature < 25:
        return 45
    elif 25 <= temperature < 30:
        return 90
    elif 30 <= temperature < 35:
        return 135
    else:
        return 180

def main():
    failure_count = 0
    use_servo2 = False

    try:
        with gpio_setup() as (servo1, servo2):
            current_angle1 = 0
            current_angle2 = 0

            while True:
                temperature = simulate_temperature()
                logging.info(f"Simulated temperature: {temperature:.2f}°C")
                target_angle = determine_servo_angle(temperature)
                logging.info(f"Target servo angle: {target_angle}°")

                if use_servo2:
                    move_servo(servo2, target_angle, current_angle2)
                    current_angle2 = target_angle
                else:
                    try:
                        if random.random() < 0.1:  # 10% failure rate
                            raise Exception("Simulated servo1 failure")
                        move_servo(servo1, target_angle, current_angle1)
                        current_angle1 = target_angle
                        failure_count = 0
                    except Exception as e:
                        logging.error(f"Servo1 failure: {e}")
                        failure_count += 1
                        if failure_count >= 3:
                            logging.info("Switching to servo2 permanently")
                            use_servo2 = True

                time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        logging.info("Cleaning up GPIO and exiting")

if __name__ == "__main__":
    main()
