import queue
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation
import serial
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
TIMEOUT = 1
FRAME_SHAPE = (24, 32)
UPDATE_INTERVAL = 100  # milliseconds

# Queue for communication between threads
frame_queue = queue.Queue()

# Event to signal the thread to stop
stop_event = threading.Event()

def read_serial_data():
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        sys.exit(1)

    while not stop_event.is_set():
        try:
            line = ser.readline().decode('ascii').strip()
            if line:
                try:
                    data = list(map(int, line.split(',')))
                    if len(data) == FRAME_SHAPE[0] * FRAME_SHAPE[1]:
                        frame_queue.put(np.array(data).reshape(FRAME_SHAPE))
                    else:
                        logging.warning("Malformed line: incorrect number of integers")
                except ValueError:
                    logging.warning("Malformed line: non-integer value encountered")
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            break

    ser.close()

def update_heatmap(frame, img):
    if frame is not None:
        img.set_data(frame)
    return img,

def main():
    # Start the serial reading thread
    serial_thread = threading.Thread(target=read_serial_data)
    serial_thread.start()

    # Set up the plot
    fig, ax = plt.subplots()
    img = ax.imshow(np.zeros(FRAME_SHAPE), cmap='inferno', interpolation='nearest')
    plt.colorbar(img, ax=ax)
    ax.set_title("Live Thermal-Imaging Heatmap")

    def animate(i):
        try:
            frame = frame_queue.get_nowait()
        except queue.Empty:
            frame = None
        return update_heatmap(frame, img)

    ani = animation.FuncAnimation(fig, animate, interval=UPDATE_INTERVAL, blit=True)

    try:
        plt.show()
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, stopping...")
    finally:
        stop_event.set()
        serial_thread.join()
        plt.close(fig)

if __name__ == "__main__":
    main()

import time
import logging
import smbus2
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DHT20:
    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REGISTER = 0x71
    COMMAND_REGISTER = 0xAC
    MEASUREMENT_COMMAND = [0x33, 0x00]
    CRC_POLYNOMIAL = 0x31
    CRC_INITIAL = 0xFF
    MAX_MEASUREMENT_ATTEMPTS = 5
    MAX_POLL_ATTEMPTS = 10
    POLL_INTERVAL = 0.08
    MEASUREMENT_INTERVAL = 2.0

    def __init__(self):
        self.bus = None
        self.last_measurement_time = 0
        self.cached_temperature = None
        self.cached_humidity = None
        self.last_error = False

    def begin(self):
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
            time.sleep(0.5)  # Wait after power-on
            status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
            if (status & 0x18) != 0x18:
                logger.error("Status check failed: 0x%02X", status)
                return False
            return True
        except OSError as e:
            logger.error("Failed to open I2C bus or read status: %s", e)
            return False

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def __enter__(self):
        if not self.begin():
            raise RuntimeError("Failed to initialize DHT20 sensor")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def _crc8(self, data):
        crc = self.CRC_INITIAL
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ self.CRC_POLYNOMIAL
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def _read_measurement(self):
        for attempt in range(self.MAX_MEASUREMENT_ATTEMPTS):
            try:
                self.bus.write_i2c_block_data(self.I2C_ADDRESS, self.COMMAND_REGISTER, self.MEASUREMENT_COMMAND)
                for _ in range(self.MAX_POLL_ATTEMPTS):
                    status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
                    if not (status & 0x80):
                        break
                    time.sleep(self.POLL_INTERVAL)
                else:
                    logger.warning("Measurement timeout")
                    continue

                data = self.bus.read_i2c_block_data(self.I2C_ADDRESS, self.STATUS_REGISTER, 7)
                if self._crc8(data[:6]) != data[6]:
                    logger.warning("CRC mismatch")
                    continue

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
                humidity = humidity_raw / 2**20 * 100
                temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
                temperature = temperature_raw / 2**19 * 200 - 50

                self.cached_temperature = temperature
                self.cached_humidity = humidity
                self.last_error = False
                return temperature, humidity, False

            except OSError as e:
                logger.error("I2C read/write error: %s", e)
                self.last_error = True

            time.sleep(0.01)  # Wait before retrying

        self.last_error = True
        return None, None, True

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_measurement_time < self.MEASUREMENT_INTERVAL:
            return self.cached_temperature, self.cached_humidity, self.last_error

        temperature, humidity, error = self._read_measurement()
        self.last_measurement_time = current_time
        return temperature, humidity, error

def demo():
    try:
        with DHT20() as sensor:
            if not sensor.begin():
                print("Failed to initialize the DHT20 sensor.")
                return

            while True:
                temperature, humidity, error = sensor.get_temperature_and_humidity()
                if error:
                    print("Failed to read temperature and humidity.")
                else:
                    print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %")
                time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        print("Exiting gracefully.")

if __name__ == "__main__":
    demo()

