class FanController:
    def __init__(self, pin):
        self.fan = PWMOutputDevice(pin, frequency=100)
        self.running = True

    def set_duty_cycle(self, duty_cycle):
        self.fan.value = duty_cycle

    def stop(self):
        self.fan.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.stop()

def read_cpu_temperature():
    try:
        # Try reading from vcgencmd
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, check=True)
        temp_str = result.stdout.strip().split('=')[1].split('\'')[0]
        return float(temp_str)
    except Exception as e:
        logging.warning(f"Failed to read temperature using vcgencmd: {e}")

    try:
        # Fallback to reading from sysfs
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            temp_str = f.read().strip()
            return float(temp_str) / 1000.0
    except Exception as e:
        logging.warning(f"Failed to read temperature from sysfs: {e}")

    return None

def get_duty_cycle(temperature):
    if temperature is None:
        return 0.0

    if temperature > 70:
        return 1.0
    elif temperature > 60:
        return 0.85
    elif temperature > 50:
        return 0.7
    elif temperature > 40:
        return 0.5
    elif temperature > 32:
        return 0.25
    elif temperature > 25:
        return 0.15
    else:
        return 0.0

def signal_handler(signum, frame):
    logging.info("Signal received, shutting down...")
    controller.running = False

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with FanController(14) as controller:
        while controller.running:
            temperature = read_cpu_temperature()
            if temperature is not None:
                logging.info(f"Current CPU Temperature: {temperature:.2f}°C")
            else:
                logging.warning("Failed to read CPU temperature.")

            duty_cycle = get_duty_cycle(temperature)
            logging.info(f"Setting fan speed to {duty_cycle * 100:.0f}%")
            controller.set_duty_cycle(duty_cycle)

            time.sleep(5)

if __name__ == "__main__":
