from ina219 import INA219, DeviceRangeError

class INA219Sensor:
    def __init__(self, address, shunt_ohms):
        self.address = address
        self.shunt_ohms = shunt_ohms
        self.sensor = None
        try:
            self.sensor = INA219(address=address, busnum=1)
            self.sensor.configure(shunt_resistance=shunt_ohms, max_expected_current=2, max_expected_power=1)
        except Exception as e:
            print(f"Error initializing INA219 sensor at address {address}: {e}")
            self.sensor = None

    def read_voltage(self):
        if self.sensor:
            try:
                return self.sensor.voltage()
            except DeviceRangeError:
                print("Voltage out of range")
            except Exception as e:
                print(f"Error reading voltage: {e}")
        return None

    def read_current(self):
        if self.sensor:
            try:
                return self.sensor.current()
            except DeviceRangeError:
                print("Current out of range")
            except Exception as e:
                print(f"Error reading current: {e}")
        return None

    def read_power(self):
        if self.sensor:
            try:
                return self.sensor.power()
            except DeviceRangeError:
                print("Power out of range")
            except Exception as e:
                print(f"Error reading power: {e}")
        return None

class UPSPlus:
    def __init__(self, address):
        self.address = address
        self.bus = smbus2.SMBus(1)

    def read_register(self, reg):
        try:
            return self.bus.read_word_data(self.address, reg)
        except Exception as e:
            print(f"Error reading register {reg}: {e}")
            return None

    def read_all_registers(self):
        data = {}
        for reg in range(0x00, 0x100):
            value = self.read_register(reg)
            if value is not None:
                data[reg] = value
        return data

    def extract_fields(self, data):
        fields = {
            "processor_voltage": self._read_big_endian(data, 0x01),
