import serial
import matplotlib.pyplot as plt
import numpy as np
import time
import sys

def read_serial_frame(serial_port):
    try:
        line = serial_port.readline().decode('utf-8').strip()
        if not line:
            return None
        try:
            frame = [int(x) for x in line.split(',')]
            if len(frame) == 768:
                return np.array(frame).reshape((24, 32))
        except ValueError:
            pass
    except Exception as e:
        print(f"Error reading from serial: {e}")
    return None

def main():
    serial_port = None
    plt.ion()
    fig, ax = plt.subplots()
    heatmap = np.zeros((24, 32))
    im = ax.imshow(heatmap, cmap='inferno', interpolation='nearest')

    try:
        serial_port = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        print("Serial port opened successfully.")
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
        sys.exit(1)

    try:
        while True:
            frame = read_serial_frame(serial_port)
            if frame is not None:
                heatmap = frame
                im.set_data(heatmap)
                plt.draw()
                plt.pause(0.1)
            else:
                print("Invalid frame received, keeping last good frame.")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if serial_port:
            serial_port.close()
            print("Serial port closed.")
        plt.close(fig)
        print("Matplotlib figure closed.")

if __name__ == "__main__":
    main()

