#!/usr/bin/env python3

import logging
import logging.handlers
import os
import random
import time
from datetime import datetime
from gpiozero import DigitalInputDevice
from signal import signal, SIGINT

# Constants
TEMP_MIN, TEMP_MAX = 10, 55
HUMID_MIN, HUMID_MAX = 20, 100
SIMULATION_INTERVAL = 5
RETRY_LIMIT = 3
RETRY_DELAY = 1
LOG_DIR_PRIMARY = "/var/log/wearable"
LOG_DIR_FALLBACK = os.path.expanduser("~/.local/log/wearable")
LOG_FILE = "sensor.log"

# Ensure log directory exists
def ensure_log_dir(log_dir):
    if not os.path.exists(log_dir):
        try:
            os.makedirs(log_dir)
        except OSError as e:
            logging.error(f"Failed to create log directory {log_dir}: {e}")
            raise

# Setup logging
def setup_logging():
    try:
        ensure_log_dir(LOG_DIR_PRIMARY)
        log_dir = LOG_DIR_PRIMARY
    except Exception:
        try:
            ensure_log_dir(LOG_DIR_FALLBACK)
            log_dir = LOG_DIR_FALLBACK
        except Exception as e:
            print(f"Cannot write logs to any directory: {e}")
            raise

    log_file_path = os.path.join(log_dir, LOG_FILE)
    handler = logging.handlers.TimedRotatingFileHandler(
        log_file_path, when="midnight", backupCount=7
    )
    formatter = logging.Formatter(
        "%(asctime)s - %(levelname)s - %(message)s", datefmt="%Y-%m-%d %H:%M:%S"
    )
    handler.setFormatter(formatter)

    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    logger.addHandler(handler)
    return logger

# Validate data
def validate_data(temperature, humidity):
    try:
        temp = float(temperature)
        hum = float(humidity)
        return TEMP_MIN <= temp <= TEMP_MAX and HUMID_MIN <= hum <= HUMID_MAX
    except (TypeError, ValueError):
        return False

# Simulate sensor reading
def simulate_sensor_reading():
    temperature = random.uniform(15, 45)
    humidity = random.uniform(40, 95)
    return temperature, humidity

# Main function
def main():
    logger = setup_logging()
    gpio_pin = DigitalInputDevice(4)  # GPIO4, BCM numbering

    def signal_handler(sig, frame):
        logger.info("Shutdown event received. Exiting gracefully.")
        gpio_pin.close()
        logging.shutdown()
        exit(0)

    signal(SIGINT, signal_handler)

    try:
        while True:
            for attempt in range(RETRY_LIMIT):
                try:
                    temperature, humidity = simulate_sensor_reading()
                    if temperature is None or humidity is None:
                        raise ValueError("Simulated sensor error")

                    if validate_data(temperature, humidity):
                        logger.info(f"Valid data - Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                    else:
                        logger.error(f"Invalid data - Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                    break
                except ValueError as e:
                    logger.error(f"Attempt {attempt + 1}: {e}")
                    if attempt < RETRY_LIMIT - 1:
                        time.sleep(RETRY_DELAY)
            time.sleep(SIMULATION_INTERVAL)
    except (OSError, TypeError, ValueError) as e:
        logger.error(f"Exception occurred: {e}")
    except Exception as e:
        logger.error(f"Unexpected exception: {e}")
    finally:
        gpio_pin.close()
        logging.shutdown()

if __name__ == "__main__":
    main()

