import smbus2
import time
import sys

# MCP23017 I2C address
MCP23017_ADDRESS = 0x20

# MCP23017 Registers
IODIRA = 0x00
IODIRB = 0x01
GPPUA = 0x0C
GPPUB = 0x0D
GPIOA = 0x12
GPIOB = 0x13
OLATA = 0x14
OLATB = 0x15

# Pin configuration
LED_PIN = 0  # GPA0
SWITCH_PIN = 7  # GPB7

# I2C bus
bus = smbus2.SMBus(0)

def write_register(register, value):
    try:
        bus.write_byte_data(MCP23017_ADDRESS, register, value)
    except Exception as e:
        print(f"Error writing to register {register}: {e}")
        raise

def read_register(register):
    try:
        return bus.read_byte_data(MCP23017_ADDRESS, register)
    except Exception as e:
        print(f"Error reading from register {register}: {e}")
        raise

def configure_mcp23017():
    try:
        # Set GPA0 as output
        write_register(IODIRA, 0xFF ^ (1 << LED_PIN))
        # Set GPB7 as input
        write_register(IODIRB, 0x00 | (1 << SWITCH_PIN))
        # Enable pull-up on GPB7
        write_register(GPPUB, 1 << SWITCH_PIN)
    except Exception as e:
        print(f"Failed to configure MCP23017: {e}")
        sys.exit(1)

def read_switch():
    try:
        gpio_b = read_register(GPIOB)
        return (gpio_b >> SWITCH_PIN) & 0x01
    except Exception as e:
        print(f"Failed to read switch state: {e}")
        return None

def set_led(state):
    try:
        current_state = read_register(OLATA)
        if state:
            write_register(OLATA, current_state | (1 << LED_PIN))
        else:
            write_register(OLATA, current_state & ~(1 << LED_PIN))
    except Exception as e:
        print(f"Failed to set LED state: {e}")

def main():
    configure_mcp23017()
    led_state = None

    try:
        while True:
            switch_state = read_switch()
            if switch_state is None:
                time.sleep(0.1)
                continue

            if switch_state == 0:  # Switch closed
                if led_state != True:
                    set_led(True)
                    print("Led ON")
                    led_state = True
            else:  # Switch open
                if led_state != False:
                    set_led(False)
                    print("Led OFF")
                    led_state = False

            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Exiting gracefully...")
    finally:
        set_led(False)  # Ensure LED is off
        bus.close()

if __name__ == "__main__":
    main()

import smbus2
import time
import signal
import sys

# Constants for MCP23017
I2C_ADDRESS = 0x20
IODIRA = 0x00
IODIRB = 0x01
GPIOA = 0x12
GPIOB = 0x13
OLATA = 0x14
OLATB = 0x15
GPPUB = 0x0C

# Pin configuration
LED_PIN = 0  # GPA0
SWITCH_PIN = 7  # GPB7

# Debounce time in seconds
DEBOUNCE_TIME = 0.02

# Initialize variables
bus = None
last_switch_state = None
led_state = False

def i2c_write_byte_data(register, value):
    try:
        bus.write_byte_data(I2C_ADDRESS, register, value)
    except Exception as e:
        raise RuntimeError(f"Failed to write to register {register:#04x}: {e}")

def i2c_read_byte_data(register):
    try:
        return bus.read_byte_data(I2C_ADDRESS, register)
    except Exception as e:
        raise RuntimeError(f"Failed to read from register {register:#04x}: {e}")

def setup_mcp23017():
    global bus
    try:
        bus = smbus2.SMBus(1)
    except FileNotFoundError:
        sys.exit("I2C bus /dev/i2c-1 not found. Please check your connection.")
    except Exception as e:
        sys.exit(f"Failed to open I2C bus: {e}")

    # Set GPA0 as output
    i2c_write_byte_data(IODIRA, 0xFF ^ (1 << LED_PIN))
    # Set GPB7 as input with pull-up
    i2c_write_byte_data(IODIRB, 0x00)
    i2c_write_byte_data(GPPUB, 1 << SWITCH_PIN)

def read_switch():
    global last_switch_state
    current_state = i2c_read_byte_data(GPIOB)
    if (current_state & (1 << SWITCH_PIN)) == 0:
        current_state = False
    else:
        current_state = True

    if current_state == last_switch_state:
        return current_state
    else:
        time.sleep(DEBOUNCE_TIME)
        current_state = i2c_read_byte_data(GPIOB)
        if (current_state & (1 << SWITCH_PIN)) == 0:
            current_state = False
        else:
            current_state = True

        if current_state == last_switch_state:
            last_switch_state = current_state
            return current_state
        else:
            return None

def cleanup():
    global bus, led_state
    if bus:
        try:
            if led_state:
                i2c_write_byte_data(OLATA, 1 << LED_PIN)
            bus.close()
        except Exception as e:
            print(f"Error during cleanup: {e}")
    sys.exit(0)

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    cleanup()

def main():
    global last_switch_state, led_state
    setup_mcp23017()
    last_switch_state = read_switch()
    led_state = False

    signal.signal(signal.SIGINT, signal_handler)

    while True:
        switch_state = read_switch()
        if switch_state is not None:
            if switch_state != last_switch_state:
                last_switch_state = switch_state
                led_state = switch_state
                i2c_write_byte_data(OLATA, (1 << LED_PIN) if led_state else 0)
                print(f"Switch state changed: {'HIGH' if led_state else 'LOW'}")

if __name__ == "__main__":
    main()

