class DOG:
    def __init__(self, pin):
        self.pin = pin
        GPIO.setup(self.pin, GPIO.IN)

    def send(self, data_string):
        # Simulate sending data
        print(f"Sending: {data_string}")

    def receive(self):
        # Simulate receiving data
        return GPIO.input(self.pin)

class Server:
    def __init__(self):
        self.running = False
        self.receive_thread = None
        self.log_file = None
        self.queue = Queue()
