import sys
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Global variables for cleanup
i2c = None
sensor = None
pwm = None

def cleanup(signum, frame):
    print("Cleaning up resources...")
    if pwm:
        pwm.stop()
    if i2c:
        i2c.deinit()
    GPIO.cleanup()
    sys.exit(0)

def setup_signal_handlers():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

def setup_i2c():
    global i2c
    try:
        i2c = busio.I2C(board.SCL1, board.SDA1)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        sys.exit(1)

def setup_sensor():
    global sensor
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c, address=0x39)
        sensor.integration_time = adafruit_tsl2561.IntegrationTime.MS_402
        sensor.gain = adafruit_tsl2561.Gain.AUTO
    except Exception as e:
        print(f"Failed to initialize TSL2561 sensor: {e}")
        sys.exit(1)

def setup_pwm():
    global pwm
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(18, GPIO.OUT)
        pwm = GPIO.PWM(18, 1000)  # 1000 Hz frequency
        pwm.start(0)
    except Exception as e:
        print(f"Failed to initialize PWM: {e}")
        sys.exit(1)

def map_lux_to_brightness(lux):
    if lux < 0:
        return 0
    elif lux >= 1000:
        return 100
    else:
        return int((lux / 1000) * 100)

def main():
    setup_signal_handlers()
    setup_i2c()
    setup_sensor()
    setup_pwm()

    try:
        while True:
            try:
                lux = sensor.lux
                brightness = map_lux_to_brightness(lux)
                pwm.ChangeDutyCycle(brightness)
                print(f"Lux: {lux:.2f}, Brightness: {brightness}%")
                time.sleep(1)
            except Exception as e:
                print(f"Error reading sensor: {e}")
                time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup(None, None)

if __name__ == "__main__":
    main()

