from gpiozero import PWMOutputDevice, OutputDevice
from contextlib import contextmanager

class PIDHandler:
    def __init__(self, pwm=True):
        self.pwm = pwm
        self.global_err_state = False
        self.last_msg = time.time()
        self.error_output = None
        self.setup_logging()
        self.setup_signal_handlers()
        self.initialize_gpio()

    def setup_logging(self):
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def initialize_gpio(self):
        try:
            if self.pwm:
                self.error_output = PWMOutputDevice(18, frequency=1000, initial_value=0.0)
            else:
                self.error_output = OutputDevice(15)
            self.logger.info("GPIO initialized successfully.")
        except Exception as e:
            self.logger.error(f"Failed to initialize GPIO: {e}")
            raise RuntimeError("GPIO initialization failed. Ensure you are running on a Raspberry Pi.")

    def update_error_output(self):
        try:
            if self.pwm:
                self.error_output.value = 1.0 if self.global_err_state else 0.0
            else:
                self.error_output.value = self.global_err_state
            self.logger.info(f"Error output updated to {'HIGH' if self.global_err_state else 'LOW'}.")
        except Exception as e:
            self.logger.error(f"Failed to update error output: {e}")

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self):
        context = zmq.Context()
        socket = context.socket(zmq.SUB)
        socket.setsockopt(zmq.SUBSCRIBE, b'')
        socket.connect("tcp://localhost:5555")

        while True:
            try:
                message = socket.recv(zmq.NOBLOCK)
                self.last_msg = time.time()
                self.logger.info("Message received.")
                # Process message and update global_err_state as needed
            except zmq.Again:
                if time.time() - self.last_msg > 20:
                    self.set_error_output(True)
                    self.logger.warning("No message received for 20 seconds. Triggering error output.")
            except Exception as e:
                self.logger.error(f"Error handling message: {e}")

    def cleanup(self, signum=None, frame=None):
        self.logger.info("Cleaning up resources.")
        if self.error_output:
            self.error_output.close()
        logging.shutdown()
        exit(0)

    def run(self):
        try:
            self.handle_message()
        except Exception as e:
            self.logger.error(f"Unexpected error: {e}")
        finally:
            self.cleanup()

if __name__ == "__main__":
    pid_handler = PIDHandler(pwm=True)
    pid_handler.run()

