import pigpio
import time
from typing import Union

class PigpioConnectionError(Exception):
    """Custom exception for pigpio connection errors."""
    pass

class InvalidPinNumberError(Exception):
    """Custom exception for invalid pin number."""
    pass

class InvalidValueError(Exception):
    """Custom exception for invalid value."""
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise InvalidPinNumberError(f"Invalid pin number: {pin_number}. Must be between 0 and 31.")
        if initial_value not in (0, 1):
            raise InvalidValueError(f"Invalid initial value: {initial_value}. Must be 0 or 1.")

        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pi = None

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise PigpioConnectionError("Failed to connect to the pigpio daemon.")
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
            self.pi.write(self.pin_number, self.initial_value)
        except Exception as e:
            if self.pi:
                self.pi.stop()
            raise e

    def set_value(self, value: int):
        if value not in (0, 1):
            raise InvalidValueError(f"Invalid value: {value}. Must be 0 or 1.")
        try:
            self.pi.write(self.pin_number, value)
        except Exception as e:
            raise RuntimeError(f"Failed to set pin value: {e}")

    def shutdown(self):
        try:
            if self.pi:
                self.pi.set_mode(self.pin_number, pigpio.INPUT)
                self.pi.stop()
        except Exception as e:
            print(f"Error during shutdown: {e}")

if __name__ == '__main__':
    try:
        output_pin = OutputPin(pin_number=17, initial_value=0)
        for _ in range(10):
            output_pin.set_value(1)
            time.sleep(0.5)
            output_pin.set_value(0)
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        output_pin.shutdown()

