            self.data([0x00, 0x00, 0x00, 0x7F])  # YSTART = 0, YEND = 127
            self.command(0x2C)  # Memory write
            self.data([color >> 8, color & 0xFF] * (WIDTH * HEIGHT // 2))
        except Exception as e:
            print(f"Failed to fill screen: {e}")

    def draw_text(self, text, font, color, x, y):
        try:
            image = Image.new('RGB', (WIDTH, HEIGHT))
            draw = ImageDraw.Draw(image)
            draw.text((x, y), text, font=font, fill=color)
            self.push_image(image)
        except Exception as e:
            print(f"Failed to draw text: {e}")

    def push_image(self, image):
        try:
            self.command(0x2A)  # Column address set
            self.data([0x00, 0x00, 0x00, image.width - 1])
            self.command(0x2B)  # Page address set
            self.data([0x00, 0x00, 0x00, image.height - 1])
            self.command(0x2C)  # Memory write
            pixels = list(image.getdata())
            for i in range(0, len(pixels), 2):
                self.data([pixels[i][1], pixels[i][0], pixels[i+1][1], pixels[i+1][0]])
        except Exception as e:
            print(f"Failed to push image: {e}")

def main():
    display = TFTDisplay()

    try:
        for color in COLORS:
            display.fill_screen(color)
            time.sleep(1)

        x, y = 0, 0
        for font_index in range(1, 9):
            font = FONTS[font_index - 1]
            for char_code in range(33, 127):
                try:
                    char = chr(char_code)
                    display.draw_text(char, font, (255, 255, 255), x, y)
                    x += font.getsize(char)[0]
                    if x >= WIDTH:
                        x = 0
                        y += font.getsize(char)[1]
                    if y >= HEIGHT:
                        x, y = 0, 0
                except Exception as e:
                    print(f"Failed to display character {char_code}: {e}")

        x, y = 0, 0
        for font_index in [3, 4]:
            font = FONTS[font_index - 1]
            for char_code in range(1, 256):
                try:
                    char = chr(char_code)
                    display.draw_text(char, font, (255, 255, 255), x, y)
                    x += font.getsize(char)[0]
                    if x >= WIDTH:
                        x = 0
                        y += font.getsize(char)[1]
                    if y >= HEIGHT:
                        x, y = 0, 0
                except Exception as e:
                    print(f"Failed to display extended character {char_code}: {e}")

        positions = [0, 32, 64, 96]
        for i, font_index in enumerate([1, 2, 3, 4]):
            font = FONTS[font_index - 1]
            color = COLORS[i]
            display.draw_text('Quick Brown fox jumped over', font, color, 0, positions[i])

        display.fill_screen(0x0000FF)  # Blue
        display.draw_text('Fin.', FONTS[7], (255, 255, 255), 0, 0)

    except KeyboardInterrupt:
        print("Program interrupted by user")
    except Exception as e:
        print(f"An error occurred: {e}")
        traceback.print_exc()
    finally:
        display.cleanup()

if __name__ == "__main__":
    main()
