        transition_table = {
            0b00: 0,  # 00 or 11
            0b01: 1,  # 01
            0b11: 3,  # 11
            0b10: 2,  # 10
        }
        direction = transition_table[new_state] - transition_table[self.state]
        self.state = new_state

        if direction == 1:
            self.counter += 1
        elif direction == 3:
            self.counter -= 1

        if self.callback and callable(self.callback):
            self.callback(self.counter)

