from contextlib import contextmanager

# Define a context manager to handle cleanup
@contextmanager
def safe_pwm_device(pin):
    pwm_device = None
    try:
        pwm_device = PWMOutputDevice(pin, frequency=25000)
        yield pwm_device
    except DeviceNotFound:
        print("Hardware PWM not available, falling back to software PWM.")
        pwm_device = PWMOutputDevice(pin, frequency=25000, pwm_freq=25000)
        yield pwm_device
    finally:
        if pwm_device:
            pwm_device.close()

def main():
    pin = 12  # GPIO12 in BCM numbering
    try:
        with safe_pwm_device(pin) as pwm_device:
            pwm_device.value = 0  # Start with 0% duty cycle

            def handle_exit(signum, frame):
                print("\nExiting and cleaning up...")
                pwm_device.value = 0
                sys.exit(0)

            # Register signal handler for graceful exit
            signal(SIGINT, handle_exit)

            while True:
                try:
                    user_input = input("Enter fan speed percentage (0-100) or 'q' to quit: ").strip().lower()
                    if user_input == 'q':
