import time

class RotaryEncoder:
    def __init__(self, clk_pin=17, dt_pin=18, debounce_time=0.005, callback=None):
        self.clk = Button(clk_pin, pull_up=True, bounce_time=debounce_time)
        self.dt = Button(dt_pin, pull_up=True, bounce_time=debounce_time)
        self.counter = 0
        self.callback = callback
        self._validate_callback()
        self._setup_event_thread()

    def _validate_callback(self):
        if self.callback is not None and not callable(self.callback):
            raise ValueError("Provided callback is not callable")

    def _setup_event_thread(self):
        self._stop_event_thread = False
        self._event_thread = Thread(target=self._event_loop)
        self._event_thread.start()

    def _event_loop(self):
        last_clk_state = self.clk.is_pressed
        while not self._stop_event_thread:
            current_clk_state = self.clk.is_pressed
            if current_clk_state != last_clk_state:
                last_clk_state = current_clk_state
                if self.dt.is_pressed:
                    self.counter += 1
                else:
                    self.counter -= 1
                self._execute_callback()
            time.sleep(0.001)  # Small delay to prevent CPU overuse

    def _execute_callback(self):
        if self.callback:
            try:
                self.callback(self.counter)
            except Exception as e:
                print(f"Callback execution failed: {e}")

    def cleanup(self):
        self._stop_event_thread = True
        self._event_thread.join()
        self.clk.close()
        self.dt.close()

if __name__ == "__main__":
