def update_leds(cpu_usage, memory_usage, disk_io):
    """Update LED colors based on usage."""
    with lock:
        for color, led in leds['cpu'].items():
            if color == 'R':
                led.value = map_usage_to_pwm(cpu_usage)
            elif color == 'G':
                led.value = map_usage_to_pwm(66 - cpu_usage)
            else:
                led.value = map_usage_to_pwm(33 - cpu_usage)

        for color, led in leds['memory'].items():
            if color == 'R':
                led.value = map_usage_to_pwm(memory_usage)
            elif color == 'G':
                led.value = map_usage_to_pwm(66 - memory_usage)
            else:
                led.value = map_usage_to_pwm(33 - memory_usage)

        for color, led in leds['disk_io'].items():
            if color == 'R':
                led.value = map_usage_to_pwm(disk_io)
            elif color == 'G':
                led.value = map_usage_to_pwm(66 - disk_io)
            else:
                led.value = map_usage_to_pwm(33 - disk_io)

def handle_signal(signum, frame):
    """Handle termination signals."""
    logging.info("Received termination signal. Cleaning up...")
    cleanup()

def cleanup():
    """Clean up resources."""
    with lock:
        for led_group in leds.values():
            for led in led_group.values():
                led.close()
        factory.close()
    logging.info("Cleanup complete.")

def connect_socket():
    """Connect to the TCP socket and handle reconnections."""
    backoff = RECONNECT_BACKOFF_INITIAL
    while True:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((HOST, PORT))
            logging.info("Connected to server.")
            return sock
        except socket.error as e:
            logging.error(f"Socket error: {e}. Reconnecting in {backoff} seconds...")
            time.sleep(backoff)
            backoff = min(backoff * 2, RECONNECT_BACKOFF_MAX)

def receive_data(sock):
    """Receive data from the socket and update LEDs."""
    while True:
        try:
            data = sock.recv(1024)
            if not data:
                raise ConnectionError("Connection closed by server.")
            message = json.loads(data.decode('utf-8'))
            cpu_usage = message.get('cpu_usage')
            memory_usage = message.get('memory_usage')
            disk_io = message.get('disk_io')

            if all(isinstance(val, (int, float)) and 0 <= val <= 100 for val in [cpu_usage, memory_usage, disk_io]):
                update_leds(cpu_usage, memory_usage, disk_io)
            else:
                logging.warning("Invalid data received. Discarding.")
        except (json.JSONDecodeError, ConnectionError) as e:
            logging.error(f"Error receiving data: {e}. Reconnecting...")
            sock.close()
            sock = connect_socket()

def main():
    """Main function to run the program."""
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        sock = connect_socket()
        receive_data(sock)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()
