import RPi.GPIO as GPIO
import logging
import random
import time
from datetime import datetime

# Configure logging
logging.basicConfig(
    filename='art_installation.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Define GPIO pins
SENSOR_PIN_1 = 17
SENSOR_PIN_2 = 18

# Define actuator functions
def activate_light():
    logging.info("Activating light")
    print("Light activated")

def activate_sound():
    logging.info("Activating sound")
    print("Sound activated")

def activate_motor():
    logging.info("Activating motor")
    print("Motor activated")

# List of actuators
ACTUATORS = [activate_light, activate_sound, activate_motor]

# Setup GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SENSOR_PIN_1, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(SENSOR_PIN_2, GPIO.IN, pull_up_down=GPIO.PUD_UP)
except RuntimeError as e:
    logging.error(f"RuntimeError during GPIO setup: {e}")
    exit(1)

def read_sensor(pin):
    try:
        return GPIO.input(pin) == GPIO.HIGH
    except Exception as e:
        logging.error(f"Error reading sensor on pin {pin}: {e}")
        return False

def main():
    last_trigger_time = None

    try:
        while True:
            sensor_1_triggered = not read_sensor(SENSOR_PIN_1)
            sensor_2_triggered = not read_sensor(SENSOR_PIN_2)

            if sensor_1_triggered or sensor_2_triggered:
                current_time = time.time()
                if last_trigger_time is None or current_time - last_trigger_time > 0.5:
                    if sensor_1_triggered:
                        logging.info(f"Intrusion Detected: Sensor 1 on GPIO {SENSOR_PIN_1}")
                    if sensor_2_triggered:
                        logging.info(f"Intrusion Detected: Sensor 2 on GPIO {SENSOR_PIN_2}")

                    if sensor_1_triggered and sensor_2_triggered:
                        logging.warning("Confirmed Intrusion: Both sensors triggered")
                        for actuator in ACTUATORS:
                            actuator()
                    else:
                        actuator = random.choice(ACTUATORS)
                        actuator()

                    last_trigger_time = current_time
                    time.sleep(0.1)  # Debounce

            time.sleep(0.05)  # Reduce CPU usage

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

