from adafruit_pca9685 import PCA9685
from adafruit_bus_device.i2c_device import I2CDevice
import board
import busio

# Configure logging
logging.basicConfig(level=logging.INFO)

class Fuchikoma:
    def __init__(self):
        self.servo_channels = {
            'claw': 0,
            'lock': 1,
            'water_gun': 2
        }
        self.angle_range = (-77, 77)
        self.min_pulse = 150  # microseconds
        self.max_pulse = 600  # microseconds
        self.frequency = 60  # Hz

        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.pca = PCA9685(self.i2c)
            self.pca.frequency = self.frequency
            logging.info("PCA9685 initialized successfully.")
        except (ValueError, OSError) as e:
            logging.error("PCA9685 not found on I2C bus: %s", e)
            self.cleanup()
            exit(1)

        atexit.register(self.cleanup)

    def map_angle_to_pulse(self, angle):
        if angle < self.angle_range[0] or angle > self.angle_range[1]:
            raise ValueError(f"Angle {angle} out of range {self.angle_range}")
        return int(self.min_pulse + (self.max_pulse - self.min_pulse) * (angle + 77) / 154)

    def move_servo(self, servo_name, angle, delay=0.029):
        if servo_name not in self.servo_channels:
            raise ValueError(f"Servo {servo_name} not recognized.")

        channel = self.servo_channels[servo_name]
        pulse_width = self.map_angle_to_pulse(angle)
        self.pca.channels[channel].duty_cycle = pulse_width * 16
        time.sleep(delay)
        self.pca.channels[channel].duty_cycle = 0

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        try:
            for channel in self.servo_channels.values():
                self.pca.channels[channel].duty_cycle = 0
            logging.info("PCA9685 channels deinitialized.")
        except Exception as e:
            logging.error("Error during cleanup: %s", e)

def main():
    fuchikoma = Fuchikoma()
    try:
        fuchikoma.bite()
        fuchikoma.open_claw()
        fuchikoma.lock()
        fuchikoma.unlock()
        fuchikoma.shoot()
    except KeyboardInterrupt:
        logging.info("Interrupted by user.")
    finally:
        fuchikoma.cleanup()

if __name__ == "__main__":
    main()

