LOCK = threading.Lock()

# Simulated sensor data
def simulate_sensor_data():
    return {
        "active_power": random.uniform(50, 200),
        "voltage": random.uniform(220, 240),
        "current": random.uniform(0.2, 1.0),
        "frequency": random.uniform(59.5, 60.5),
        "power_factor": random.uniform(0.8, 1.0),
        "timestamp": datetime.datetime.now().isoformat()
    }

# File management
def get_log_filename():
    date_str = datetime.datetime.now().strftime("%Y-%m-%d")
    return os.path.join(LOG_DIR, f"energy_log_{date_str}.json")

def compress_log_file(filename):
    try:
        with open(filename, 'rb') as f_in:
            with gzip.open(f"{filename}.gz", 'wb') as f_out:
                f_out.writelines(f_in)
        os.remove(filename)
    except Exception as e:
        logging.error(f"Error compressing file {filename}: {e}")

def rotate_log_file():
    filename = get_log_filename()
    if os.path.exists(filename) and os.path.getsize(filename) > MAX_FILE_SIZE:
        with LOCK:
            compress_log_file(filename)

def ensure_log_directory():
    if not os.path.exists(LOG_DIR):
        os.makedirs(LOG_DIR)

# Data acquisition thread
def data_acquisition(queue):
    ensure_log_directory()
    while True:
        try:
            for address in I2C_ADDRESSES:
                data = simulate_sensor_data()
                data["address"] = address
                queue.put(data)
                rotate_log_file()
                time.sleep(5)
        except Exception as e:
            logging.error(f"Error in data acquisition: {e}")

# File writing thread
def file_writer(queue):
    ensure_log_directory()
    while True:
        data = queue.get()
        if data is None:
            break
        try:
            filename = get_log_filename()
            with LOCK:
                with open(filename, 'a') as f:
                    f.write(json.dumps(data) + '\n')
                    os.chmod(filename, 0o600)
        except Exception as e:
            logging.error(f"Error writing to file: {e}")

# CLI menu
def display_menu():
    while True:
        print("\nMenu:")
        print("1. View current readings")
        print("2. View data for a given date")
        print("3. Display min/max/avg active power for a given sensor and date")
        print("4. Quit")
        choice = input("Enter your choice: ")
        if choice == '1':
            view_current_readings()
        elif choice == '2':
            view_data_for_date()
        elif choice == '3':
            display_power_stats()
        elif choice == '4':
            break
        else:
            print("Invalid choice. Please try again.")

def view_current_readings():
    with LOCK:
        filename = get_log_filename()
        if os.path.exists(filename):
            with open(filename, 'r') as f:
                lines = f.readlines()[-10:]  # Show last 10 readings
                for line in lines:
                    print(json.loads(line))
        else:
            print("No current readings available.")

def view_data_for_date():
    date_str = input("Enter date (YYYY-MM-DD): ")
    filename = os.path.join(LOG_DIR, f"energy_log_{date_str}.json")
    if os.path.exists(filename):
        with open(filename, 'r') as f:
            for line in f:
                print(json.loads(line))
    else:
        print("No data available for the given date.")

def display_power_stats():
    date_str = input("Enter date (YYYY-MM-DD): ")
    address = int(input("Enter sensor address (0x3B, 0x3C, 0x3D): "), 16)
    filename = os.path.join(LOG_DIR, f"energy_log_{date_str}.json")
    if os.path.exists(filename):
        powers = []
        with open(filename, 'r') as f:
            for line in f:
                data = json.loads(line)
                if data["address"] == address:
                    powers.append(data["active_power"])
        if powers:
            print(f"Min: {min(powers)}, Max: {max(powers)}, Avg: {sum(powers)/len(powers)}")
        else:
            print("No data available for the given sensor and date.")
    else:
        print("No data available for the given date.")

# Main function
def main():
    queue = Queue()
    acquisition_thread = threading.Thread(target=data_acquisition, args=(queue,))
    writer_thread = threading.Thread(target=file_writer, args=(queue,))
    acquisition_thread.start()
    writer_thread.start()

    try:
        display_menu()
    finally:
        queue.put(None)
        writer_thread.join()
        acquisition_thread.join()

if __name__ == "__main__":
    main()
