from gpiozero import LED
from gpiozero.exc import PinSetupException

def simulate_water_quality_reading():
    """Simulate a water quality reading as a percentage from 0 to 100."""
    if random.random() < 0.1:  # 10% chance of failure
        raise ValueError("Sensor read failure")
    return random.randint(0, 100)

def main():
    led = None
    try:
        # Initialize the LED on GPIO18
        led = LED(18)
        print("LED initialized on GPIO18.")

        for i in range(5):
            try:
                reading = simulate_water_quality_reading()
                print(f"Reading {i + 1}: {reading}%")

                if reading < 50:
                    led.on()
                    print("Water quality is poor. LED is ON.")
                else:
                    led.off()
                    print("Water quality is acceptable. LED is OFF.")

            except ValueError as e:
                print(f"Error: {e}. Retrying...")
                try:
                    reading = simulate_water_quality_reading()
                    print(f"Retried Reading {i + 1}: {reading}%")

                    if reading < 50:
                        led.on()
                        print("Water quality is poor. LED is ON.")
                    else:
                        led.off()
                        print("Water quality is acceptable. LED is OFF.")

                except ValueError as retry_e:
                    print(f"Retry failed: {retry_e}. Skipping this reading.")

            time.sleep(2)

    except PinSetupException as e:
        print(f"GPIO setup error: {e}")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        if led is not None:
            led.close()
            print("LED resources released.")

if __name__ == "__main__":
    main()

