import time
import signal
import logging
from busio import I2C
from board import SCL, SDA
from adafruit_tcs34725 import TCS34725, IntegrationTime, Gain
from PIL import Image, UnidentifiedImageError
import os

# Configure logging
logging.basicConfig(level=logging.INFO)

# Global variables
i2c = None
sensor = None

def signal_handler(sig, frame):
    logging.info("Signal received, shutting down...")
    cleanup()
    exit(0)

def cleanup():
    global i2c
    if i2c:
        i2c.deinit()
    logging.info("Resources released.")

def initialize_i2c():
    global i2c
    try:
        i2c = I2C(SCL, SDA)
        logging.info("I2C bus initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        cleanup()
        exit(1)

def initialize_sensor():
    global sensor
    try:
        sensor = TCS34725(i2c, integration_time=IntegrationTime.INTEGRATION_TIME_50MS, gain=Gain.GAIN_4X)
        logging.info("TCS34725 sensor initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize TCS34725 sensor: {e}")
        cleanup()
        exit(1)

def get_sensor_color_data():
    try:
        color = sensor.color_rgb_bytes
        return (color[0], color[1], color[2], sensor.clear)
    except Exception as e:
        logging.error(f"Failed to read from sensor: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(10000)  # Get up to 10,000 colors
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
    except FileNotFoundError:
        logging.error("Image file not found.")
    except UnidentifiedImageError:
        logging.error("Corrupt image file.")
    except Exception as e:
        logging.error(f"Error processing image: {e}")
    return (0, 0, 0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_i2c()
    initialize_sensor()

    try:
        while True:
            sensor_data = get_sensor_color_data()
            logging.info(f"Sensor Data: R={sensor_data[0]}, G={sensor_data[1]}, B={sensor_data[2]}, Clear={sensor_data[3]}")

            dominant_color = find_dominant_image_color('image.jpg')
            logging.info(f"Dominant Image Color: R={dominant_color[0]}, G={dominant_color[1]}, B={dominant_color[2]}")

            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, shutting down...")
    finally:
        cleanup()

if __name__ == "__main__":
