# Configure logging
logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
HOST = '127.0.0.1'
PORT = 9099
SERIAL_PORT = '/dev/ttyAMA0'
SERIAL_BAUDRATE = 9600
I2C_ADDRESS = 0x42
GPS_TIMEOUT = 2

# Global variables
tracking_state = 'stopped'
gps_serial = None
gps_bus = None
gps_device = None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info("Shutting down...")
    cleanup()
    sys.exit(0)

# Context manager for serial connection
@contextmanager
def serial_connection():
    try:
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=GPS_TIMEOUT)
        yield ser
    except serial.SerialException as e:
        logging.error(f"Serial connection error: {e}")
        yield None
    finally:
        if ser and ser.is_open:
            ser.close()

# Context manager for I2C connection
@contextmanager
def i2c_connection():
    try:
        bus = SMBus(1)
        yield bus
    except Exception as e:
        logging.error(f"I2C connection error: {e}")
        yield None
    finally:
        if bus:
            bus.close()

# Initialize GPS module
def init_gps():
    global gps_serial, gps_bus, gps_device
    try:
        with serial_connection() as ser:
            if ser:
                gps_serial = ser
                return
    except Exception as e:
        logging.error(f"Failed to initialize GPS via serial: {e}")

    try:
        with i2c_connection() as bus:
            if bus:
                gps_bus = bus
                gps_device = I2C_ADDRESS
                return
    except Exception as e:
        logging.error(f"Failed to initialize GPS via I2C: {e}")

    logging.error("No GPS module found. Falling back to simulated coordinates.")

# Read GPS position
def read_gps_position():
    if gps_serial:
        try:
            line = gps_serial.readline().decode('ascii', errors='replace').strip()
            if line.startswith('$GPGGA'):
                parts = line.split(',')
                if len(parts) >= 6:
                    lat = float(parts[2])
                    lon = float(parts[4])
                    return {'lat': lat, 'lon': lon}
        except Exception as e:
            logging.error(f"Error reading GPS via serial: {e}")
    elif gps_bus and gps_device:
        try:
            # Simulate reading from I2C device
            # This is a placeholder for actual I2C read logic
            lat = 37.7749  # Simulated latitude
            lon = -122.4194  # Simulated longitude
            return {'lat': lat, 'lon': lon}
        except Exception as e:
            logging.error(f"Error reading GPS via I2C: {e}")

    logging.error("Failed to read GPS position. Returning simulated coordinates.")
    return {'lat': 37.7749, 'lon': -122.4194}  # Simulated coordinates

# Handle incoming command
def handle_command(client_socket):
    try:
        command = client_socket.recv(1024).decode('utf-8').strip()
        if command == 'start':
            global tracking_state
            tracking_state = 'running'
            response = json.dumps({'status': 'tracking started'})
        elif command == 'stop':
            tracking_state = 'stopped'
            response = json.dumps({'status': 'tracking stopped'})
        elif command == 'report':
            position = read_gps_position()
            response = json.dumps(position)
        else:
            response = json.dumps({'error': 'invalid command'})
    except Exception as e:
        logging.error(f"Error handling command: {e}")
        response = json.dumps({'error': 'internal error'})

    client_socket.sendall(response.encode('utf-8'))

# Main function
def main():
    global gps_serial, gps_bus
    init_gps()

    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.settimeout(GPS_TIMEOUT)
    server_socket.bind((HOST, PORT))
    server_socket.listen(1)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            try:
                client_socket, _ = server_socket.accept()
                handle_command(client_socket)
                client_socket.close()
            except socket.timeout:
                continue
            except socket.error as e:
                logging.error(f"Socket error: {e}")
    finally:
        cleanup()

# Cleanup resources
def cleanup():
    global gps_serial, gps_bus, server_socket
    if gps_serial and gps_serial.is_open:
        gps_serial.close()
    if gps_bus:
        gps_bus.close()
    if server_socket:
        server_socket.close()

if __name__ == '__main__':
    main()

