import time
from datetime import datetime

# Constants
PIR_PIN = 4
FEEDING_TIMES = [(7, 0, 8, 0), (18, 0, 19, 0)]
DEBOUNCE_DELAY = 60  # seconds

# Initialize variables
last_feeding_time = 0

def is_feeding_time(now):
    """Check if the current time is within feeding times."""
    for start_hour, start_minute, end_hour, end_minute in FEEDING_TIMES:
        start = now.replace(hour=start_hour, minute=start_minute, second=0, microsecond=0)
        end = now.replace(hour=end_hour, minute=end_minute, second=0, microsecond=0)
        if start <= now <= end:
            return True
    return False

def log_event(message):
    """Log an event with a timestamp."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    print(f"{timestamp} - {message}")

def setup_gpio():
    """Set up GPIO."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

def cleanup_gpio():
    """Clean up GPIO."""
    GPIO.cleanup()

def main():
    try:
        setup_gpio()
        print("PIR Motion Sensor Monitoring Started")

        while True:
            try:
                if GPIO.input(PIR_PIN):
                    now = datetime.now()
                    log_event("Motion detected")

                    if is_feeding_time(now):
                        if (now - last_feeding_time).total_seconds() >= DEBOUNCE_DELAY:
                            last_feeding_time = now
                            log_event(f"Feeding initiated at {now.strftime('%Y-%m-%d %H:%M:%S')}")
                        else:
                            log_event("Not feeding time or recently fed.")
                    else:
                        log_event("Not feeding time or recently fed.")

                    time.sleep(DEBOUNCE_DELAY)
                else:
                    time.sleep(1)

            except Exception as e:
                print(f"Runtime error: {e}")
                cleanup_gpio()
                break

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"Error during setup: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

