import atexit
import signal
import logging
from Adafruit_MotorHAT import Adafruit_MotorHAT, Adafruit_DCMotor
from Adafruit_GPIO import I2C
from Adafruit_GPIO.I2C import I2CError

# Configure logging
logging.basicConfig(level=logging.INFO)

class DCMotorHATExtra(Adafruit_MotorHAT):
    def __init__(self, address=0x60, busnum=1, freq=60):
        try:
            self.i2c = I2C.get_i2c_device(address, busnum)
            super().__init__(self.i2c)
            self.set_pwm_freq(freq)
        except I2CError as e:
            logging.error(f"I2C communication error: {e}")
            raise

    def set_pwm_freq(self, freq):
        self._pwm.setPWMFreq(freq)

    def get_pwm_freq(self):
        return self._pwm.getPWMFreq()

    def release_motors(self):
        for i in range(1, 5):
            motor = self.getMotor(i)
            motor.run(Adafruit_MotorHAT.RELEASE)

def signal_handler(sig, frame):
    logging.info("Signal received, shutting down...")
    motor_hat.release_motors()
    exit(0)

def atexit_handler():
    logging.info("Exiting program, releasing motors...")
    motor_hat.release_motors()

class DCMotor:
    def __init__(self, motor_hat, motor_num, pwm_freq=None, invert=False):
        if motor_num < 1 or motor_num > 4:
            raise ValueError("Motor number must be between 1 and 4")
        self.motor_hat = motor_hat
        self.motor = motor_hat.getMotor(motor_num)
        self.motor_num = motor_num
        self.invert = invert
        self.last_dc = 0
        self.pwm_freq = pwm_freq if pwm_freq else motor_hat.get_pwm_freq()

    def set_dc(self, duty_cycle):
        try:
            if duty_cycle == 0:
                self.stop()
                return

            if duty_cycle < -255 or duty_cycle > 255:
                logging.warning("Duty cycle out of range, clamping to -255 to 255")
                duty_cycle = max(-255, min(255, duty_cycle))

            if duty_cycle == self.last_dc:
                return

            direction = Adafruit_MotorHAT.FORWARD if (duty_cycle > 0) ^ self.invert else Adafruit_MotorHAT.BACKWARD
            speed = abs(duty_cycle)
            self.motor.run(direction)
            self.motor.setSpeed(speed)
            self.last_dc = duty_cycle
        except Exception as e:
            logging.error(f"Error setting duty cycle: {e}")

    def stop(self):
        self.set_dc(0)

    def close(self):
        self.stop()

    def get_status(self):
        return {
            "motor_num": self.motor_num,
            "pwm_freq": self.pwm_freq,
            "invert": self.invert,
            "last_dc": self.last_dc
        }

# Example usage
if __name__ == "__main__":
    motor_hat = DCMotorHATExtra()
    atexit.register(atexit_handler)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    motor = DCMotor(motor_hat, motor_num=1)

    try:
        for dc in range(0, 256, 5):
            motor.set_dc(dc)
            logging.info(f"Ramping up: {dc}")
        for dc in range(255, -256, -5):
            motor.set_dc(dc)
            logging.info(f"Ramping down: {dc}")
    except Exception as e:
        logging.error(f"Error during motor operation: {e}")
    finally:
        motor.close()

