import pigpio

class MotorError(Exception):
    """Custom exception for motor control errors."""
    pass

class Motor:
    def __init__(self, pi, pin):
        if not isinstance(pi, pigpio.pi):
            raise MotorError("Invalid pigpio.pi instance.")

        self.pi = pi
        self.pin = pin
        self.pwm_handle = None

        try:
            self.pi.set_mode(self.pin, pigpio.OUTPUT)
            self.pwm_handle = self.pi.set_PWM_frequency(self.pin, 1000)
            if self.pwm_handle < 0:
                raise MotorError("Failed to set PWM frequency.")
            self.set_duty_cycle(0)
        except Exception as e:
            self.close()
            raise MotorError(f"Initialization failed: {e}")

    def set_frequency(self, freq):
        if not isinstance(freq, int) or freq <= 0:
            raise MotorError("Frequency must be a positive integer.")

        try:
            result = self.pi.set_PWM_frequency(self.pin, freq)
            if result < 0:
                raise MotorError("Failed to set PWM frequency.")
        except Exception as e:
            raise MotorError(f"Failed to set frequency: {e}")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or not (0 <= duty <= 255):
            raise MotorError("Duty cycle must be an integer between 0 and 255.")

        try:
            result = self.pi.set_PWM_dutycycle(self.pin, duty)
            if result < 0:
                raise MotorError("Failed to set PWM duty cycle.")
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}")

    def stop(self):
        try:
            self.set_duty_cycle(0)
        except Exception as e:
            raise MotorError(f"Failed to stop motor: {e}")

    def close(self):
        try:
            if self.pwm_handle is not None:
                self.pi.set_PWM_dutycycle(self.pin, 0)
                self.pi.set_PWM_frequency(self.pin, 0)
        except Exception as e:
            raise MotorError(f"Failed to close motor: {e}")

    def __del__(self):
        self.stop()
        self.close()

