import signal
import time
from gpiozero import AngularServo, exc
from contextlib import contextmanager

class RoboticArm:
    def __init__(self, base_pin, shoulder_pin, gripper_pin):
        self.base_servo = AngularServo(base_pin, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
        self.shoulder_servo = AngularServo(shoulder_pin, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
        self.gripper_servo = AngularServo(gripper_pin, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)

    def move_joint(self, servo, target_angle):
        try:
            clamped_angle = max(-90, min(90, target_angle))
            servo.value = clamped_angle
            time.sleep(0.4)  # Settling delay
        except exc.OutputDeviceBadValue:
            print(f"Invalid angle: {target_angle}. Clamped to [-90, 90].")
        except ValueError as e:
            print(f"ValueError: {e}")
        except RuntimeError as e:
            print(f"RuntimeError: {e}")

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        self.base_servo.angle = None
        self.shoulder_servo.angle = None
        self.gripper_servo.angle = None

@contextmanager
def cleanup_on_exit(robot_arm):
    try:
        yield
    finally:
        robot_arm.release()

def run_demo_sequence(robot_arm):
    poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20), (0, 0, 0)]
    for pose in poses:
        print(f"Moving to pose: {pose}")
        robot_arm.go_to_pose(*pose)
        time.sleep(1)  # Pause to observe the pose

def signal_handler(sig, frame, robot_arm):
    print("Signal received, releasing servos and exiting.")
    robot_arm.release()
    exit(0)

def main():
    robot_arm = RoboticArm(base_pin=17, shoulder_pin=27, gripper_pin=22)

    # Setup signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, lambda sig, frame: signal_handler(sig, frame, robot_arm))
    signal.signal(signal.SIGTERM, lambda sig, frame: signal_handler(sig, frame, robot_arm))

    with cleanup_on_exit(robot_arm):
        run_demo_sequence(robot_arm)

if __name__ == "__main__":
    main()

