import logging
import signal
import sys
import time
from automationhat import relay, input
from automationhat import AutomationHATError

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GarageDoor:
    def __init__(self, state_pin):
        self.state_pin = state_pin
        self.relay = relay.one
        self.input_channel = input.one
        self._setup_input()
        self._setup_relay()

    def _setup_input(self):
        try:
            self.input_channel.set_mode('input')
            self.input_channel.set_pull('up')
        except AutomationHATError as e:
            logging.error(f"Failed to setup input channel: {e}")
            sys.exit(0)

    def _setup_relay(self):
        try:
            self.relay.set_mode('output')
            self.relay.off()
        except AutomationHATError as e:
            logging.error(f"Failed to setup relay: {e}")
            sys.exit(0)

    @property
    def state(self):
        try:
            value = self.input_channel.read()
            if value is None:
                raise ValueError("Input read returned None")
            return value
        except (AutomationHATError, ValueError) as e:
            logging.error(f"Error reading state: {e}")
            return None

    def trigger(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except AutomationHATError as e:
            logging.error(f"Error triggering relay: {e}")

def cleanup():
    try:
        relay.one.off()
    except AutomationHATError:
        pass

def signal_handler(sig, frame):
    logging.info("Signal received, shutting down...")
    cleanup()
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        My_Garage = GarageDoor(state_pin=1)
    except AutomationHATError:
        logging.error("Automation HAT not connected or not installed.")
        sys.exit(0)

    while True:
        try:
            current_state = My_Garage.state
            if current_state is None:
                logging.warning("State is None, skipping action.")
                continue

            if current_state == 1:
                logging.info("Garage door is closed. Triggering to open.")
                My_Garage.trigger()
            elif current_state == 0:
                logging.info("Garage door is open. Triggering to close.")
                My_Garage.trigger()
            else:
                logging.error(f"Unexpected state value: {current_state}")

            time.sleep(1)

        except AutomationHATError as e:
            logging.error(f"Automation HAT error: {e}")
            cleanup()
            sys.exit(0)

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()

