from gpiozero import OutputDevice, Servo
from time import sleep
import signal
import sys

class Laser:
    def __init__(self, pin=17):
        try:
            self.laser = OutputDevice(pin)
        except Exception as e:
            print(f"Error initializing Laser: {e}")
            sys.exit(1)

    def on(self):
        try:
            self.laser.on()
        except Exception as e:
            print(f"Error turning laser on: {e}")

    def off(self):
        try:
            self.laser.off()
        except Exception as e:
            print(f"Error turning laser off: {e}")

    def close(self):
        try:
            self.laser.close()
        except Exception as e:
            print(f"Error closing laser: {e}")

class Aim:
    def __init__(self, ld, sd, horizontal_pin=18, vertical_pin=19):
        self.ld = ld
        self.sd = sd
        try:
            self.horizontal_servo = Servo(horizontal_pin)
            self.vertical_servo = Servo(vertical_pin)
            self.hp = [i / 9.0 for i in range(10)]
            self.vp = [i / 9.0 for i in range(10)]
        except Exception as e:
            print(f"Error initializing Aim: {e}")
            sys.exit(1)

    def aim(self, nums, laser):
        try:
            for num in nums:
                b = num - 1
                if 0 <= b < 10:
                    self.horizontal_servo.value = self.hp[b]
                    self.vertical_servo.value = self.vp[b]
                    sleep(self.sd / 2)
                    laser.on()
                    sleep(self.ld)
                    laser.off()
                    sleep(self.sd / 2)
            # Move to neutral position
            self.horizontal_servo.value = self.hp[9]
            self.vertical_servo.value = self.vp[9]
        except Exception as e:
            print(f"Error during aiming: {e}")
        finally:
            laser.off()

    def close(self):
        try:
            self.horizontal_servo.close()
            self.vertical_servo.close()
        except Exception as e:
            print(f"Error closing servos: {e}")

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    laser.close()
    aim.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    laser = Laser()
    aim = Aim(ld=1.0, sd=0.5)

    try:
        # Example usage: aim at targets 1, 3, and 5
        aim.aim([1, 3, 5], laser)
    except KeyboardInterrupt:
        print("Interrupted by user")
    finally:
        laser.close()
        aim.close()

