import logging
import signal
import schedule
import time
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOPinInUseError, DigitalOutputDeviceError
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pin
GPIO_PIN = 17

# Context manager to handle GPIO resource cleanup
@contextmanager
def gpio_device(pin):
    device = None
    try:
        device = DigitalOutputDevice(pin)
        yield device
    except GPIOPinInUseError as e:
        logging.error(f"GPIO pin {pin} is already in use: {e}")
    except Exception as e:
        logging.error(f"Error initializing GPIO device: {e}")
    finally:
        if device:
            try:
                device.close()
            except Exception as e:
                logging.error(f"Error closing GPIO device: {e}")

def activate_motor():
    try:
        logging.info("Activating motor.")
        motor.value = True
    except DigitalOutputDeviceError as e:
        logging.error(f"Error activating motor: {e}")

def deactivate_motor():
    try:
        logging.info("Deactivating motor.")
        motor.value = False
    except DigitalOutputDeviceError as e:
        logging.error(f"Error deactivating motor: {e}")

def motor_routine():
    try:
        activate_motor()
        time.sleep(30)
        deactivate_motor()
    except Exception as e:
        logging.error(f"Error during motor routine: {e}")

def signal_handler(sig, frame):
    logging.info("Received shutdown signal. Cleaning up...")
    if motor:
        deactivate_motor()
    exit(0)

def main():
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Schedule the motor routine
    schedule.every().day.at("21:14").do(motor_routine)

    # Initialize GPIO device
    global motor
    with gpio_device(GPIO_PIN) as motor:
        if motor is None:
            logging.error("Failed to initialize motor. Exiting.")
            return

        logging.info("Motor initialized successfully. Starting scheduler loop.")
        try:
            while True:
                schedule.run_pending()
                time.sleep(1)
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
        finally:
            if motor:
                deactivate_motor()

if __name__ == "__main__":
    main()

