            sys.exit(1)

    def send_command(self, command):
        logging.info(f"Sending command: {command}")
        self.serial.write((command + "\r\n").encode())
        return self.read_response()

    def read_response(self, attempts=5):
        response = b""
        for _ in range(attempts):
            try:
                response += self.serial.read(self.serial.in_waiting or 1)
                if b"OK" in response:
                    logging.info(f"Received response: {response.decode().strip()}")
                    return response.decode().strip()
            except serial.SerialTimeoutException:
                logging.warning("Read timeout occurred.")
        logging.error("Failed to receive a valid response.")
        return None

    def set_gps_reporting(self, interval_seconds=10):
        logging.info(f"Setting GPS reporting interval to {interval_seconds} seconds...")
        response = self.send_command(f"AT+GPSRD={interval_seconds}")
        if response != "OK":
            logging.error("Failed to set GPS reporting interval.")
            return False
        return True

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        logging.info(f"Sending TCP data to {ip}:{port}...")
        if not self.send_command(f"AT+CIPSTART=\"TCP\",\"{ip}\",{port}"):
            logging.error("Failed to start TCP connection.")
            return False
        if not self.send_command(f"AT+CIPSEND"):
            logging.error("Failed to initiate data send.")
            return False
        self.serial.write(data.encode() + b"\x1A")
        if not self.read_response():
            logging.error("Failed to send data.")
            return False
        self.send_command("AT+CIPCLOSE")
        return True

    def send_terminator(self):
        logging.info("Sending terminator...")
        self.serial.write(b"\x1A")
        return self.read_response()

    def set_message_storage(self, storage='SM'):
        logging.info(f"Setting message storage to {storage}...")
        response = self.send_command(f"AT+CPMS=\"{storage}\",\"{storage}\",\"{storage}\"")
        if response != "OK":
            logging.error("Failed to set message storage.")
            return False
        return True

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources...")
        if self.serial:
            self.serial.close()
        GPIO.cleanup()

    def signal_handler(self, signum, frame):
        logging.info(f"Received signal {signum}. Exiting...")
        self.cleanup()
        sys.exit(0)

def main():
    signal.signal(signal.SIGINT, GSMModule.signal_handler)
    signal.signal(signal.SIGTERM, GSMModule.signal_handler)

    with GSMModule() as gsm:
        gsm.set_gps_reporting()
        gsm.send_tcp_data("Hello, GSM!")
        gsm.set_message_storage()

if __name__ == "__main__":
    main()
```

