import RPi.GPIO as GPIO
import time
import datetime
import logging

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

# Constants
RELAY_PIN = 17
SUNRISE_TIME = datetime.time(7, 0)
SUNSET_TIME = datetime.time(19, 0)
CHECK_INTERVAL = 60  # seconds

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT)
        GPIO.output(RELAY_PIN, GPIO.LOW)  # Ensure door is open at start
    except Exception as e:
        logging.error(f"Failed to set up GPIO: {e}")
        raise

def control_door():
    try:
        while True:
            now = datetime.datetime.now().time()
            if SUNSET_TIME <= now or now <= SUNRISE_TIME:
                # Close the door at sunset
                if GPIO.input(RELAY_PIN) == GPIO.LOW:
                    logging.info("Closing the door.")
                    GPIO.output(RELAY_PIN, GPIO.HIGH)
                    time.sleep(1)
            else:
                # Open the door at sunrise
                if GPIO.input(RELAY_PIN) == GPIO.HIGH:
                    logging.info("Opening the door.")
                    GPIO.output(RELAY_PIN, GPIO.LOW)
                    time.sleep(1)
            time.sleep(CHECK_INTERVAL)
    except KeyboardInterrupt:
        logging.info("Script interrupted by user.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleaned up.")

if __name__ == "__main__":
    try:
        setup_gpio()
        control_door()
    except Exception as e:
        logging.error(f"Failed to start the script: {e}")

