from contextlib import contextmanager

class AimingController:
    def __init__(self, ld, hd):
        self.ld = ld
        self.hd = hd
        self.servo_positions = {
            'hx': [133, 128, 122, 133, 128, 122, 133, 128, 122, 128],
            'vy': [75, 75, 75, 72, 72, 72, 68, 68, 68, 90]
        }
        self.laser = OutputDevice(17)
        self.servo_file = None
        self._setup_signal_handlers()
        self._open_servoblaster()

    def _setup_signal_handlers(self):
        def signal_handler(sig, frame):
            self.cleanup()
            sys.exit(0)
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

    def _open_servoblaster(self):
        try:
            self.servo_file = open('/dev/servoblaster', 'w')
        except IOError as e:
            print(f"Error opening /dev/servoblaster: {e}")
            sys.exit(1)

    def _set_servo_position(self, channel, position):
        if self.servo_file:
            try:
                self.servo_file.write(f"{channel}={position}\n")
                self.servo_file.flush()
            except IOError as e:
                print(f"Error writing to /dev/servoblaster: {e}")

    def aim_blocks(self, nums):
        try:
            sorted_positions = sorted(enumerate(nums), key=lambda x: x[1])
            for index, _ in sorted_positions:
                self._set_servo_position(0, self.servo_positions['hx'][index])
                self._set_servo_position(1, self.servo_positions['vy'][index])
                time.sleep(self.ld / 2)
                self.laser.on()
                time.sleep(self.hd)
                self.laser.off()
                time.sleep(self.ld / 2)
        except Exception as e:
            print(f"Error during aiming: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.laser.is_active:
            self.laser.off()
        if self.servo_file:
            self.servo_file.close()

    def __del__(self):
        self.cleanup()

