import smbus2
from contextlib import contextmanager

class I2CDevice:
    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus_number = bus_number
        self.bus = smbus2.SMBus(bus_number)
        self._probe_device()

    def _probe_device(self):
        try:
            # Perform a quick I2C address probe
            self.bus.read_byte(self.address)
        except (OSError, IOError):
            self.bus.close()
            raise RuntimeError(f"Device at address {self.address} not found on bus {self.bus_number}")

    def write_byte(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to write byte to register {register}: {e}")

    def read_byte(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to read byte from register {register}: {e}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

