        self._cleanup()
        sys.exit(0)

    def _verify_device(self):
        try:
            self.bus.read_byte(self.I2C_ADDRESS)
        except OSError:
            raise RuntimeError("DS1338 RTC not found on I2C bus")

    def _cleanup(self):
        if self.bus:
            self.bus.close()

    def _bcd_to_int(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _int_to_bcd(self, value):
        return ((value // 10) << 4) + (value % 10)

    def _validate_time(self, hours, minutes, seconds):
        if not (0 <= hours < 24):
            raise ValueError("Hours must be in 0-23 range")
        if not (0 <= minutes < 60):
            raise ValueError("Minutes must be in 0-59 range")
        if not (0 <= seconds < 60):
            raise ValueError("Seconds must be in 0-59 range")

    def _validate_date(self, day, month, year):
        if not (1 <= day <= 31):
            raise ValueError("Day must be in 1-31 range")
        if not (1 <= month <= 12):
            raise ValueError("Month must be in 1-12 range")
        if not (0 <= year <= 99):
            raise ValueError("Year must be in 0-99 range")

    def read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.I2C_ADDRESS, reg)
        except OSError as e:
            print(f"Error reading register {reg}: {e}")
            return None

    def write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.I2C_ADDRESS, reg, value)
        except OSError as e:
            print(f"Error writing register {reg}: {e}")

    def read_datetime(self, century=21):
        try:
            seconds = self._bcd_to_int(self.read_register(self.REG_SECONDS))
            minutes = self._bcd_to_int(self.read_register(self.REG_MINUTES))
            hours = self._bcd_to_int(self.read_register(self.REG_HOURS) & 0x3F)
            day = self._bcd_to_int(self.read_register(self.REG_DATE))
            month = self._bcd_to_int(self.read_register(self.REG_MONTH))
            year = self._bcd_to_int(self.read_register(self.REG_YEAR)) + century * 100

            return datetime(year, month, day, hours, minutes, seconds)
        except Exception as e:
            print(f"Error reading datetime: {e}")
            return None

    def write_all(self, seconds=None, minutes=None, hours=None, day=None, month=None, year=None):
        try:
            if hours is not None:
                self._validate_time(hours, minutes, seconds)
                hours = self._int_to_bcd(hours)
                hours &= 0x3F  # Clear bit 6 for 24-hour format

            if day is not None and month is not None and year is not None:
                self._validate_date(day, month, year - century * 100)
                day = self._int_to_bcd(day)
                month = self._int_to_bcd(month)
                year = self._int_to_bcd(year % 100)

            if seconds is not None:
                seconds = self._int_to_bcd(seconds)
                self.write_register(self.REG_SECONDS, seconds)

            if minutes is not None:
                minutes = self._int_to_bcd(minutes)
                self.write_register(self.REG_MINUTES, minutes)

            if hours is not None:
                self.write_register(self.REG_HOURS, hours)

            if day is not None:
                self.write_register(self.REG_DATE, day)

            if month is not None:
                self.write_register(self.REG_MONTH, month)

            if year is not None:
                self.write_register(self.REG_YEAR, year)

        except ValueError as e:
            print(f"Invalid input: {e}")

