import smbus2
import sys
from datetime import datetime, timezone

class DS1338:
    def __init__(self, bus_number=1, address=0x68):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_number)
        except Exception as e:
            raise IOError(f"Failed to open SMBus: {e}")

    def close(self):
        if self.bus:
            self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.address, reg)
        except Exception as e:
            raise IOError(f"Failed to read register {reg:#04x}: {e}")

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.address, reg, value)
        except Exception as e:
            raise IOError(f"Failed to write register {reg:#04x}: {e}")

    def _bcd_to_decimal(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _decimal_to_bcd(self, decimal):
        return ((decimal // 10) << 4) + (decimal % 10)

    def read_all(self):
        try:
            seconds = self._read_register(0x00) & 0x7F  # Mask CH bit
            minutes = self._read_register(0x01)
            hours = self._read_register(0x02) & 0x3F  # Mask 12/24-hour bit
            day = self._read_register(0x03)
            date = self._read_register(0x04)
            month = self._read_register(0x05)
            year = self._read_register(0x06) + 2000

            return (
                self._bcd_to_decimal(year),
                self._bcd_to_decimal(month),
                self._bcd_to_decimal(date),
                self._bcd_to_decimal(day),
                self._bcd_to_decimal(hours),
                self._bcd_to_decimal(minutes),
                self._bcd_to_decimal(seconds),
            )
        except IOError as e:
            raise IOError(f"Failed to read all registers: {e}")

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (1 <= day <= 7):
            raise ValueError("Day must be between 1 and 7")
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")

        self._write_register(0x00, self._decimal_to_bcd(seconds) & 0x7F)  # Clear CH bit
        self._write_register(0x01, self._decimal_to_bcd(minutes))
        self._write_register(0x02, self._decimal_to_bcd(hours) & 0x3F)  # 24-hour mode
        self._write_register(0x03, self._decimal_to_bcd(day))
        self._write_register(0x04, self._decimal_to_bcd(date))
        self._write_register(0x05, self._decimal_to_bcd(month))
        self._write_register(0x06, self._decimal_to_bcd(year - 2000))

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        now = datetime.now(timezone.utc)
        self.write_datetime(now)

if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current RTC time: {current_time}")
    except IOError as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)
    except Exception as e:
        sys.stderr.write(f"Unexpected error: {e}\n")
        sys.exit(1)
    sys.exit(0)

