import serial
import time
import signal
import sys
from datetime import datetime

# Global flag for clean shutdown
shutdown_flag = False

def signal_handler(sig, frame):
    global shutdown_flag
    shutdown_flag = True
    print("Signal received, shutting down...")

def read_co2():
    try:
        with serial.Serial('/dev/ttyUSB0', 9600, timeout=1) as ser:
            while not shutdown_flag:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            co2_concentration = int(line)
                            timestamp = datetime.now().isoformat()
                            print(f"CO2 Concentration: {co2_concentration} ppm")
                            log_reading(timestamp, co2_concentration)
                        except ValueError:
                            print("Error: Non-numeric payload received.")
                    else:
                        print("Error: Empty payload received.")
                except serial.SerialException as e:
                    print(f"SerialException: {e}")
                    break
                time.sleep(5)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except IOError as e:
        print(f"IOError: {e}")

def log_reading(timestamp, co2_concentration):
    try:
        with open("co2_readings_log.txt", "a") as log_file:
            log_file.write(f"{timestamp}, {co2_concentration}\n")
    except IOError as e:
        print(f"Failed to write to log file: {e}")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        read_co2()
    finally:
        print("Exiting program.")

