# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPSReadings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None

class GPSReader:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None

    def connect(self):
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to {self.port} at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.serial_port = None

    def disconnect(self):
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                logging.info(f"Disconnected from {self.port}.")
            except serial.SerialException as e:
                logging.error(f"Failed to close serial port {self.port}: {e}")
        self.serial_port = None

    def _nmea_to_decimal(self, nmea, direction):
        if not nmea:
            return None
        degrees = int(nmea[:2])
        minutes = float(nmea[2:])
        decimal = degrees + minutes / 60.0
        if direction in ['S', 'W']:
            decimal *= -1
        return decimal

    def _parse_gpgga(self, sentence):
        try:
            fields = sentence.split(',')
            if fields[0][3:] != 'GGA' or len(fields) < 15:
                raise ValueError("Invalid GPGGA sentence")

            latitude = self._nmea_to_decimal(fields[2], fields[3])
            longitude = self._nmea_to_decimal(fields[4], fields[5])
            altitude = float(fields[9])
            satellite_count = int(fields[7])

            return GPSReadings(latitude, longitude, altitude, satellite_count)
        except (ValueError, IndexError) as e:
            logging.error(f"Failed to parse GPGGA sentence: {sentence}. Error: {e}")
            return None

    def run(self):
        self.connect()
        if not self.serial_port:
            return

        def signal_handler(sig, frame):
            logging.info("Signal received, shutting down.")
            self.disconnect()
            exit(0)

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        try:
            while True:
                line = self.serial_port.readline().decode('ascii', errors='replace').strip()
                if line.startswith('$GPGGA'):
                    readings = self._parse_gpgga(line)
                    if readings:
                        logging.info(f"GPS Readings: {readings}")
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
        finally:
            self.disconnect()

if __name__ == "__main__":
    gps_reader = GPSReader()
    gps_reader.run()

