        self.baudrate = baudrate
        self.connection = None

    def connect(self):
        try:
            self.connection = serial.Serial(self.port, self.baudrate, timeout=1)
            logging.info(f"Connected to {self.port} at {self.baudrate} baud.")
            return True
        except (serial.SerialException, OSError) as e:
            logging.error(f"Failed to connect to {self.port}: {e}")
            return False

    def read_data(self):
        if not self.connection or self.connection.closed:
            logging.error("Connection is closed or not established.")
            return None

        try:
            line = self.connection.readline().decode('utf-8', errors='ignore').strip()
            if line:
                return line
            return None
        except serial.SerialException as e:
            logging.error(f"Serial error occurred: {e}")
            return None

    def parse_gga(self, sentence):
        try:
            if not sentence.startswith(('$GPGGA', '$GNGGA')):
                return None

            parts = sentence.split(',')
            if len(parts) < 15:
                return None

            utc_time = parts[1]
            latitude = self._convert_to_decimal(parts[2], parts[3])
            longitude = self._convert_to_decimal(parts[4], parts[5])
            fix_quality = int(parts[6])
            num_satellites = int(parts[7])

            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
            return None

    def _convert_to_decimal(self, value, direction):
        if not value:
            return None

        degrees = float(value[:2])
        minutes = float(value[2:])
        decimal = degrees + minutes / 60.0

        if direction in ('S', 'W'):
            decimal = -decimal

        return decimal

    def close(self):
        if self.connection and not self.connection.closed:
            try:
                self.connection.close()
                logging.info("Serial connection closed.")
            except Exception as e:
                logging.error(f"Error closing connection: {e}")
        self.connection = None

