            if line:
                if line.startswith('$GPGGA') or line.startswith('$GNGGA'):
                    parsed_data = gps.parse_gga(line)
                    if parsed_data:
                        logging.info(f"Parsed GGA data: {parsed_data}")
    except KeyboardInterrupt:
        logging.info("Interrupted by user, closing connection.")
    finally:
        gps.close()

