from flask import Flask, request, jsonify, Response
import serial
import threading
import json

app = Flask(__name__)

# In-memory data store
data_store = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]
next_id = 3
data_store_lock = threading.Lock()

def read_serial_port():
    try:
        with serial.Serial('/dev/ttyUSB0', 9600, timeout=1) as ser:
            ser.write(b'*IDN?\n')
            threading.Event().wait(0.1)
            response = ser.read_all().decode('utf-8')
            return response
    except serial.SerialException as e:
        return f"Serial error: {str(e)}"
    except Exception as e:
        return f"Unexpected error: {str(e)}"

@app.route('/version', methods=['GET'])
def version():
    response = read_serial_port()
    if "Serial error" in response or "Unexpected error" in response:
        return Response(response, status=503, mimetype='text/html')
    return Response(response.replace('\n', '<br>'), mimetype='text/html')

@app.route('/getdata', methods=['GET'])
def get_data():
    with data_store_lock:
        return jsonify(data_store)

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    with data_store_lock:
        item = next((item for item in data_store if item['id'] == item_id), None)
        if item is None:
            return jsonify({"error": "Item not found"}), 404
        return jsonify(item)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post(item_id, name):
    with data_store_lock:
        new_item = {"id": item_id, "name": name, "done": False}
        data_store.append(new_item)
        return jsonify(data_store)

@app.route('/postjson', methods=['POST'])
def post_json():
    try:
        if request.content_type == 'application/json':
            data = request.get_json()
        else:
            data = request.form.to_dict()

        name = data.get('name', '')
        done_str = data.get('done', 'False')
        done = done_str.lower() in ['true', '1', 't', 'y', 'yes']

        with data_store_lock:
            new_item = {"id": next_id, "name": name, "done": done}
            data_store.append(new_item)
            global next_id
            next_id += 1

        return jsonify(data_store)
    except Exception as e:
        return jsonify({"error": "Malformed input", "details": str(e)}), 400

@app.route('/postjson', methods=['GET'])
def get_post_json():
    with data_store_lock:
        return jsonify(data_store)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

