import serial
import time
import sys

def send_command(ser, command):
    try:
        # Prefix the command with 'X' and append a newline character
        full_command = f'X{command}\n'
        ser.write(full_command.encode('utf-8'))
        time.sleep(0.1)  # Delay to avoid flooding the device
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

def main():
    ser = None
    try:
        # Establish a serial connection
        ser = serial.Serial('/dev/rfcomm4', 38400, timeout=1)

        print("Connected to Bluetooth device. Type 'exit' to quit.")

        while True:
            # Prompt the user for a command
            command = input("Enter command: ")

            if command.lower() == 'exit':
                break

            try:
                send_command(ser, command)
            except RuntimeError as e:
                print(f"Error: {e}")

    except serial.SerialException as e:
        raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")

    except KeyboardInterrupt:
        print("\nExiting gracefully...")

    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    main()
